'use client';

import { FormEvent, Fragment, ReactNode, useCallback, useEffect, useMemo, useState } from 'react';
import { usePathname, useRouter } from 'next/navigation';
import { enumLabel, Language, localizeError, t } from './i18n';
import { formatCurrency, formatDate, formatDateTime, formatMonthYear, formatQuantity } from './formatters';
import { AppIcon, IconName, IconButton, OdinBrandLogo } from './ui-icons';
import { allRoutes, canAccess, ModuleDefinition, modules, routeEntry } from './navigation';
import { useSession } from './session-provider';
import { ApprovalWorkspace, CustomerWorkspace, EmployeeWorkspace, SalesDocumentsWorkspace, SalesOverviewPage } from './sales-workspace';
import { AccessWorkspace } from './access-workspace';

type Json = any;
const API = '/api';
let displayLanguage: Language = 'en';
const money = (minor: string | number | bigint | null | undefined) => formatCurrency(minor, 'EGP', displayLanguage);
const qty = (milli: string | number | bigint | null | undefined) => formatQuantity(milli, displayLanguage);
const date = (value?: string) => formatDate(value, displayLanguage);
const dateTime = (value?: string) => formatDateTime(value, displayLanguage);
const monthYear = (value?: string) => formatMonthYear(value, displayLanguage);
const today = () => new Date().toISOString().slice(0, 10);
const baseTitle = (value: string) => value.replace(/([a-z0-9])([A-Z])/g, '$1 $2').replaceAll('_', ' ').toLowerCase().replace(/\b\w/g, (letter) => letter.toUpperCase());
const title = (value: string) => enumLabel(value, displayLanguage) !== value ? enumLabel(value, displayLanguage) : t(baseTitle(value), displayLanguage);
const initials = (value = '') => value.split(' ').map((word) => word[0]).join('').slice(0, 2).toUpperCase();

const salesTypes = ['QUOTATION', 'SALES_ORDER', 'DELIVERY_NOTE', 'SALES_INVOICE', 'SALES_RETURN', 'CREDIT_NOTE'];
const purchaseTypes = ['PURCHASE_REQUEST', 'PURCHASE_RFQ', 'PURCHASE_ORDER', 'GOODS_RECEIPT', 'PURCHASE_BILL', 'PURCHASE_RETURN'];
const inventoryTypes = ['WAREHOUSE_TRANSFER', 'INVENTORY_ADJUSTMENT', 'STOCK_COUNT'];
const conversionMap: Record<string, string[]> = { QUOTATION: ['SALES_ORDER'], SALES_ORDER: ['DELIVERY_NOTE'], DELIVERY_NOTE: ['SALES_INVOICE'], SALES_INVOICE: ['SALES_RETURN', 'CREDIT_NOTE'], PURCHASE_REQUEST: ['PURCHASE_RFQ'], PURCHASE_RFQ: ['PURCHASE_ORDER'], PURCHASE_ORDER: ['GOODS_RECEIPT'], GOODS_RECEIPT: ['PURCHASE_BILL', 'PURCHASE_RETURN'], PURCHASE_BILL: ['PURCHASE_RETURN'] };
const documentPermissionResources: Record<string, string> = {
  QUOTATION: 'sales.quotation', SALES_ORDER: 'sales.order', DELIVERY_NOTE: 'sales.delivery', SALES_INVOICE: 'sales.invoice', SALES_RETURN: 'sales.return', CREDIT_NOTE: 'sales.credit_note',
  PURCHASE_REQUEST: 'purchasing.request', PURCHASE_RFQ: 'purchasing.rfq', PURCHASE_ORDER: 'purchasing.order', GOODS_RECEIPT: 'purchasing.receipt', PURCHASE_BILL: 'purchasing.bill', PURCHASE_RETURN: 'purchasing.return',
  WAREHOUSE_TRANSFER: 'inventory.transfer', INVENTORY_ADJUSTMENT: 'inventory.adjustment', STOCK_COUNT: 'inventory.stock_count',
};
const documentPermission = (type: string, action: string) => `${documentPermissionResources[type]}.${action}`;
const masterCreatePermissions: Record<string, string> = { customer: 'sales.customer.create', supplier: 'purchasing.supplier.create', item: 'inventory.item.create', category: 'inventory.item.create', unit: 'inventory.item.create', warehouse: 'inventory.warehouse.create', bank: 'banking.account.create' };
const fieldPermission = (fields: Json[] = [], resource: string, field: string) => fields.find((entry) => entry.resource === resource && entry.field === field)?.access || 'HIDDEN';

const referenceName = (value?: string, fallback = '—') => value ? t(value, displayLanguage) : fallback;
const itemName = (item: Json) => displayLanguage === 'ar' && item?.nameAr && item.nameAr !== item.name ? item.nameAr : referenceName(item?.name);
const auditValues = (values: Json) => Object.entries(values || {}).map(([key, value]) => `${t(baseTitle(key), displayLanguage)}: ${typeof value === 'string' ? t(value, displayLanguage) : String(value)}`).join(' · ') || '—';

export default function OdinApp({ initialRoute = '/dashboard', initialLanguage = 'en' }: { initialRoute?: string; initialLanguage?: Language }) {
  const router = useRouter();
  const pathname = usePathname();
  const route = pathname === '/' ? initialRoute : pathname;
  const current = routeEntry(route);
  const { status: sessionStatus, token, user, sessionMessage, establishSession, endSession, authorizedFetch } = useSession();
  const [refs, setRefs] = useState<Json>(null);
  const [theme, setTheme] = useState('light');
  const [language, setLanguage] = useState<Language>(initialLanguage);
  const [mobileNav, setMobileNav] = useState(false);
  const [collapsed, setCollapsed] = useState(false);
  const [expandedModule, setExpandedModule] = useState<string>(current.module.id);
  const [accountMenu, setAccountMenu] = useState(false);
  const [toast, setToast] = useState<{ text: string; error?: boolean }[]>([]);

  displayLanguage = language;

  const notify = useCallback((text: string, error = false) => {
    const item = { text, error }; setToast((items) => [...items, item]);
    window.setTimeout(() => setToast((items) => items.filter((entry) => entry !== item)), 3500);
  }, []);

  const request = useCallback(async (path: string, options: RequestInit = {}) => {
    const response = await authorizedFetch(`${API}${path}`, { cache: 'no-store', ...options, headers: { ...(options.body ? { 'Content-Type': 'application/json' } : {}), 'Accept-Language': language, 'X-Odin-Language': language, ...options.headers } });
    const contentType = response.headers.get('content-type') || '';
    const result = contentType.includes('json') ? await response.json() : await response.text();
    if (!response.ok) throw new Error(localizeError(result.message || result.error || String(result), language));
    return result;
  }, [authorizedFetch, language]);

  const loadRefs = useCallback(async () => setRefs(await request('/bootstrap')), [request]);

  useEffect(() => {
    const savedTheme = localStorage.getItem('odin_theme') || 'light'; setTheme(savedTheme); document.documentElement.dataset.theme = savedTheme;
    const savedCollapse = localStorage.getItem('odin_sidebar_collapsed') === 'true'; setCollapsed(savedCollapse);
    displayLanguage = initialLanguage; localStorage.setItem('odin_language', initialLanguage); document.documentElement.lang = initialLanguage; document.documentElement.dir = initialLanguage === 'ar' ? 'rtl' : 'ltr';
  }, [initialLanguage]);

  useEffect(() => { if (token && user) loadRefs().catch((error) => notify(error.message, true)); }, [token, user, loadRefs, notify]);
  useEffect(() => { setExpandedModule(current.module.id); }, [current.module.id]);

  const navigate = (nextRoute: string) => { router.push(nextRoute); setMobileNav(false); setAccountMenu(false); };
  const toggleCollapsed = () => setCollapsed((value) => { const next = !value; localStorage.setItem('odin_sidebar_collapsed', String(next)); return next; });
  const changeTheme = () => { const next = theme === 'light' ? 'dark' : 'light'; setTheme(next); localStorage.setItem('odin_theme', next); document.documentElement.dataset.theme = next; };
  const changeLanguage = () => { const next = language === 'en' ? 'ar' : 'en'; displayLanguage = next; setLanguage(next); localStorage.setItem('odin_language', next); document.cookie = `odin_language=${next}; path=/; max-age=31536000; samesite=lax`; document.documentElement.lang = next; document.documentElement.dir = next === 'ar' ? 'rtl' : 'ltr'; router.refresh(); };
  const logout = () => { endSession(); setRefs(null); };

  if (sessionStatus === 'restoring') return <SessionRestoring language={language}/>;
  if (!user) return <Login onLogin={establishSession} sessionMessage={sessionMessage} theme={theme} changeTheme={changeTheme} language={language} changeLanguage={changeLanguage}/>;

  const visibleModules = modules.filter((module) => module.children.some((child) => canAccess(user.permissions, child.permission)));

  return <>
    <div className={`app-shell ${collapsed ? 'sidebar-is-collapsed' : ''}`}>
      {mobileNav ? <button className="nav-backdrop" aria-label={t('Close', language)} onClick={() => setMobileNav(false)}/> : null}
      <aside className={`sidebar ${mobileNav ? 'open' : ''} ${collapsed ? 'collapsed' : ''}`}>
        <div className="sidebar-head">
          <button className="brand-lockup nav-brand" onClick={() => navigate('/dashboard')}><OdinBrandLogo/><span className="brand-name">ODIN <b className="accent">ERP</b></span></button>
          <IconButton icon="close" label={t('Close', language)} className="mobile-nav-close" onClick={() => setMobileNav(false)}/>
        </div>
        <SidebarNavigation modules={visibleModules} permissions={user.permissions} currentRoute={route} expandedModule={expandedModule} setExpandedModule={setExpandedModule} collapsed={collapsed} navigate={navigate} language={language}/>
        <button data-testid="sidebar-collapse" className="sidebar-collapse" onClick={toggleCollapsed} title={t(collapsed ? 'Expand sidebar' : 'Collapse sidebar', language)}><AppIcon name="next" size={15}/><span>{t(collapsed ? 'Expand sidebar' : 'Collapse sidebar', language)}</span></button>
      </aside>
      <div className="workspace">
        <header className="topbar">
          <IconButton icon="menu" label={t('Menu', language)} className="mobile-menu" onClick={() => setMobileNav(!mobileNav)}/>
          <div className="workspace-context"><span>{t('Current company', language)}</span><strong>{t(refs?.tenant?.name || 'Odin Distribution Egypt', language)}</strong></div>
          <span className="context-separator"/>
          <div className="workspace-context page-context"><span>{t('Current page', language)}</span><strong>{t(current.child.label, language)}</strong></div>
          <label className="global-search"><AppIcon name="search" size={16}/><input aria-label={t('Search Odin ERP', language)} placeholder={t('Search Odin ERP', language)}/></label>
          <div className="top-actions">
            <button data-testid="account-menu" className="user-pill" aria-expanded={accountMenu} onClick={() => setAccountMenu((value) => !value)} title={t('Account menu', language)}><b className="avatar">{initials(user.name)}</b><span><strong>{t(user.name, language)}</strong><small>{t(user.role, language)}</small></span><AppIcon name="next" size={13}/></button>
            {accountMenu ? <div className="account-menu">
              <div className="account-menu-head"><strong>{t(user.name, language)}</strong><span>{user.email}</span></div>
              <button data-testid="language-toggle" onClick={changeLanguage}><span>{t('English / العربية', language)}</span><b>{language === 'en' ? 'ع' : 'EN'}</b></button>
              <button onClick={changeTheme}><span>{t('Toggle light mode', language)}</span><AppIcon name={theme === 'light' ? 'themeDark' : 'themeLight'} size={16}/></button>
              <button className="danger-menu-item" onClick={logout}><span>{t('Sign out', language)}</span><AppIcon name="logout" size={16}/></button>
            </div> : null}
          </div>
        </header>
        <main id="main">
          <Breadcrumbs current={current} navigate={navigate}/>
          {!refs ? <Loading label="Loading secured company data…"/> : <Page route={route} user={user} refs={refs} request={request} authorizedFetch={authorizedFetch} notify={notify} refreshRefs={loadRefs} navigate={navigate}/>} 
        </main>
      </div>
    </div>
    <div className="toast-region">{toast.map((item, index) => <div key={index} className={`toast ${item.error ? 'error' : 'success'}`}>{t(item.error ? 'Action blocked' : 'Completed', language)} · {t(item.text, language)}</div>)}</div>
  </>;
}

function SidebarNavigation({ modules: visibleModules, permissions, currentRoute, expandedModule, setExpandedModule, collapsed, navigate, language }: { modules: readonly ModuleDefinition[]; permissions: readonly string[]; currentRoute: string; expandedModule: string; setExpandedModule: (module: string) => void; collapsed: boolean; navigate: (route: string) => void; language: Language }) {
  return <nav aria-label={t('ERP modules', language)}>
    {visibleModules.map((module, index) => {
      const active = currentRoute === module.route || module.children.some((child) => child.route === currentRoute);
      const expanded = !collapsed && expandedModule === module.id;
      const visibleChildren = module.children.filter((child) => canAccess(permissions, child.permission));
      const defaultRoute = canAccess(permissions, module.permission) ? module.route : visibleChildren[0]?.route;
      const showCategory = index === 0 || visibleModules[index - 1]?.category !== module.category;
      return <Fragment key={module.id}>
        {showCategory ? <div className="nav-category">{t(module.category.toUpperCase(), language)}</div> : null}
        <section className={`nav-module ${active ? 'active' : ''}`}>
        <button data-testid={`nav-${module.id}`} className="nav-parent" aria-expanded={expanded} title={collapsed ? t(module.label, language) : undefined} onClick={() => {
          if ((collapsed || module.children.length === 1) && defaultRoute) navigate(defaultRoute);
          else setExpandedModule(expanded ? '' : module.id);
        }}>
          <span className="nav-icon"><AppIcon name={module.icon} size={18}/></span>
          <span className="nav-label">{t(module.label, language)}</span>
          {module.children.length > 1 ? <AppIcon name="next" size={13} className={`nav-chevron ${expanded ? 'open' : ''}`}/> : null}
        </button>
        {expanded ? <div className="nav-children">{visibleChildren.map((child) => <button key={child.id} data-testid={`nav-${child.id}`} className={`nav-child ${child.route === currentRoute ? 'active' : ''}`} onClick={() => navigate(child.route)}><span>{t(child.label, language)}</span></button>)}</div> : null}
        </section>
      </Fragment>;
    })}
  </nav>;
}

function Breadcrumbs({ current, navigate }: { current: ReturnType<typeof routeEntry>; navigate: (route: string) => void }) {
  return <nav className="breadcrumbs" aria-label={t('Breadcrumbs', displayLanguage)}>
    <button onClick={() => navigate(current.module.route)}>{t(current.module.label, displayLanguage)}</button>
    <AppIcon name="next" size={13}/>
    <span>{t(current.child.label, displayLanguage)}</span>
  </nav>;
}

function Login({ onLogin, sessionMessage, theme, changeTheme, language, changeLanguage }: { onLogin: (result: Json) => void; sessionMessage?: string; theme: string; changeTheme: () => void; language: Language; changeLanguage: () => void }) {
  const [email, setEmail] = useState('admin@odin.demo'), [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(true), [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState(''), [busy, setBusy] = useState(false);
  const [challenge, setChallenge] = useState<Json>(null), [mfaCode, setMfaCode] = useState(''), [recoveryCode, setRecoveryCode] = useState('');
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError('');
    try {
      const response = challenge
        ? await fetch(`${API}/auth/mfa/verify`, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ challengeToken: challenge.challengeToken, code: mfaCode, recoveryCode }) })
        : await fetch(`${API}/auth/login`, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email, password, rememberMe }) });
      const result = await response.json();
      if (!response.ok) throw new Error(result.message);
      if (result.mfaRequired || result.mfaEnrollmentRequired) setChallenge(result);
      else onLogin(result);
    }
    catch (reason: any) { setError(localizeError(reason.message || 'Sign in failed', language)); } finally { setBusy(false); }
  };
  return <section className="login-screen">
    <div className="login-brand"><OdinBrandLogo className="large" decorative/></div>
    <form className="login-panel" onSubmit={submit}>
      <div className="login-theme-toggle"><IconButton icon={theme === 'light' ? 'themeDark' : 'themeLight'} label={t('Toggle light mode', language)} onClick={changeTheme}/><button data-testid="login-language-toggle" type="button" className="icon-button" onClick={changeLanguage} title={t('English / العربية', language)}>{language === 'en' ? 'ع' : 'EN'}</button></div>
      <div className="brand-lockup"><OdinBrandLogo/><span>ODIN <b className="accent">ERP</b></span></div>
      <p className="utility-label">{t('ENTERPRISE RESOURCE PLANNING', language)}</p><h1>{t('Total visibility.', language)}<br/>{t('Complete control.', language)}</h1>
      <p className="login-copy">{t('Complete workflows from one interface, then inspect the resulting ledger, stock, report, permission and audit evidence.', language)}</p>
      {!challenge ? <><label>{t('Email', language)}<input data-testid="login-email" type="email" value={email} onChange={(event) => setEmail(event.target.value)} autoComplete="username" required/></label>
      <label>{t('Password', language)}<input data-testid="login-password" type={showPassword ? 'text' : 'password'} value={password} onChange={(event) => setPassword(event.target.value)} autoComplete="current-password" required/></label>
      <div className="login-options">
        <label className="remember-session"><input data-testid="show-password" type="checkbox" checked={showPassword} onChange={(event) => setShowPassword(event.target.checked)}/><span>{t('Show password', language)}</span></label>
        <label className="remember-session"><input type="checkbox" checked={rememberMe} onChange={(event) => setRememberMe(event.target.checked)}/><span>{t('Keep me signed in on this device', language)}</span></label>
      </div></> : <div className="mfa-login-step"><h2>{t(challenge.mfaEnrollmentRequired ? 'Set up multi-factor authentication' : 'Multi-factor authentication', language)}</h2>{challenge.mfaEnrollmentRequired ? <><p>{t('Add this secret to your authenticator app, then store the recovery codes securely.', language)}</p><code dir="ltr">{challenge.secret}</code><details><summary>{t('One-time recovery codes', language)}</summary>{challenge.recoveryCodes.map((code: string) => <code dir="ltr" key={code}>{code}</code>)}</details></> : null}<label>{t('Six-digit authentication code', language)}<input data-testid="mfa-code" inputMode="numeric" pattern="[0-9]{6}" autoComplete="one-time-code" value={mfaCode} onChange={(event) => setMfaCode(event.target.value)} required={!recoveryCode}/></label><label>{t('Recovery code', language)}<input dir="ltr" value={recoveryCode} onChange={(event) => setRecoveryCode(event.target.value)} placeholder={t('Use only if your authenticator is unavailable', language)}/></label></div>}
      <button data-testid="login-submit" className="button primary wide" disabled={busy}>{t(busy ? 'Authenticating…' : challenge ? 'Verify and continue' : 'Enter Odin ERP', language)}<AppIcon name="next"/></button>
      <p className="form-error" role="alert">{error || sessionMessage}</p>
      {!challenge ? <details className="credential-hint"><summary>{t('Twelve role-based demo profiles', language)}</summary><div><code>admin@odin.demo</code><code>cfo@odin.demo</code><code>finance@odin.demo</code><code>accountant@odin.demo</code><code>auditor@odin.demo</code><code>sales@odin.demo</code><code>sales.employee@odin.demo</code><code>purchasing@odin.demo</code><code>warehouse@odin.demo</code><code>cashier@odin.demo</code><code>hr@odin.demo</code><code>branch@odin.demo</code><p>{t('Password: password', language)}</p></div></details> : null}
    </form>
  </section>;
}

function Loading({ label = 'Loading…' }: { label?: string }) { return <div className="loading"><div><div className="spinner"/>{t(label, displayLanguage)}</div></div>; }
function SessionRestoring({ language }: { language: Language }) { return <section className="session-restoring" aria-live="polite"><div><OdinBrandLogo/><div className="spinner"/><span>{t('Restoring your session…', language)}</span></div></section>; }
function Empty({ icon = 'inbox', heading, text }: { icon?: IconName; heading: string; text: string }) { return <div className="empty-state"><i><AppIcon name={icon} size={30}/></i><strong>{t(heading, displayLanguage)}</strong><span>{t(text, displayLanguage)}</span></div>; }
function AccessDenied({ route }: { route: string }) { return <section className="access-denied" role="alert"><span><AppIcon name="lock" size={34}/></span><p className="utility-label">403 · {t('Access Denied', displayLanguage)}</p><h1>{t('You cannot open this page.', displayLanguage)}</h1><p>{t('Your role does not include the required permission. Contact your Super Admin if you need access.', displayLanguage)}</p><code dir="ltr">{route}</code></section>; }
function Status({ value }: { value: string }) { return <span className={`status ${value}`}>{title(value)}</span>; }
function PageHead({ title: heading, subtitle, children }: { title: string; subtitle: string; children?: ReactNode }) { return <div className="page-head"><div><h1>{t(heading, displayLanguage)}</h1><p>{t(subtitle, displayLanguage)}</p></div><div className="page-head-actions">{children}</div></div>; }
function Panel({ title: heading, meta, children, wide = false }: { title: string; meta?: string; children: ReactNode; wide?: boolean }) { return <section className={`panel ${wide ? 'wide-panel' : ''}`}><div className="panel-head"><h2>{t(heading, displayLanguage)}</h2>{meta && <span>{t(meta, displayLanguage)}</span>}</div><div className="panel-body">{children}</div></section>; }

function Page({ route, user, refs, request, authorizedFetch, notify, refreshRefs, navigate }: { route: string; user: Json; refs: Json; request: (path: string, options?: RequestInit) => Promise<Json>; authorizedFetch: (input: RequestInfo | URL, init?: RequestInit) => Promise<Response>; notify: (message: string, error?: boolean) => void; refreshRefs: () => Promise<void>; navigate: (route: string) => void }) {
  const allowed = (permission: string) => canAccess(user.permissions, permission);
  const current = routeEntry(route);
  const { child, module } = current;
  if (!allowed(child.permission)) return <AccessDenied route={route}/>;
  const salesProps = { user, refs, request, authorizedFetch, notify, refreshRefs, navigate, language: displayLanguage };
  if (child.id === 'sales-overview') return <SalesOverviewPage {...salesProps}/>;
  if (child.masterKind === 'customer') return <CustomerWorkspace {...salesProps}/>;
  if (child.masterKind === 'employee') return <EmployeeWorkspace {...salesProps}/>;
  if (module.id === 'sales' && child.screen === 'documents') return <SalesDocumentsWorkspace selectedType={child.documentType!} {...salesProps}/>;
  if (child.screen === 'approvals') return <ApprovalWorkspace pageTitle={child.label} {...salesProps}/>;
  if (child.screen === 'dashboard') return <Dashboard request={request}/>;
  if (child.screen === 'domain-overview') return <DomainOverview module={module.id} permissions={user.permissions} refs={refs} request={request} navigate={navigate}/>;
  if (child.screen === 'documents') {
    return <Documents module={module.id} selectedType={child.documentType!} permissions={user.permissions} fieldPermissions={user.fieldPermissions} refs={refs} request={request} notify={notify} refreshRefs={refreshRefs} navigate={navigate}/>;
  }
  if (child.screen === 'master-data') return <MasterDataPage kind={child.masterKind!} permissions={user.permissions} fieldPermissions={user.fieldPermissions} refs={refs} request={request} notify={notify} refreshRefs={refreshRefs}/>;
  if (child.screen === 'accounting') return <Accounting pageTitle={child.label} screenId={child.id} refs={refs} request={request} notify={notify} refreshRefs={refreshRefs} canWrite={allowed('accounting.journal.create')} canApprove={allowed('accounting.journal.approve')} canPost={allowed('accounting.journal.post')} canManagePeriods={allowed('accounting.period.manage')}/>;
  if (child.screen === 'payments') return <Payments pageTitle={child.label} refs={refs} request={request} notify={notify} canWrite={allowed('payments.receipt.create') || allowed('payments.payment.create')}/>;
  if (child.screen === 'pos') return <Pos refs={refs} request={request} notify={notify}/>;
  if (child.screen === 'banking') return <Banking pageTitle={child.label} screenId={child.id} refs={refs} request={request} notify={notify} refreshRefs={refreshRefs} canWrite={allowed('banking.transaction.create')} canReconcile={allowed('banking.statement.reconcile')}/>;
  if (child.screen === 'reports') return <Reports pageTitle={child.label} request={request} notify={notify} canProfit={allowed('reports.profitability.view')} category={child.reportCategory} initialReport={child.initialReport}/>;
  if (child.screen === 'audit') return <Audit pageTitle={child.label} request={request} notify={notify} canReset={allowed('settings.system.reset')}/>;
  if (child.screen === 'access') return <AccessWorkspace page={child.id.replace('access-', '') as 'users' | 'roles' | 'permissions' | 'audit'} request={request} notify={notify} language={displayLanguage} navigate={navigate}/>;
  if (child.screen === 'system-health') return <SystemHealth/>;
  return <Empty heading="Module unavailable" text={`No screen is configured for ${route}.`}/>;
}

function Dashboard({ request }: { request: (path: string) => Promise<Json> }) {
  const [data, setData] = useState<Json>(null);
  useEffect(() => { request('/dashboard').then(setData); }, [request]);
  if (!data) return <Loading label="Reconciling live ledgers…"/>;
  const k = data.kpis;
  const low = data.lowStock.filter((row: Json) => BigInt(row.quantityMilli) <= BigInt(row.item.reorderMilli));
  return <div className="page dashboard-page"><PageHead title="Command Center" subtitle="Management overview across sales, cash, working capital and operational exceptions"/>
    <div className="metric-grid primary-kpis"><Metric label="SALES" value={money(k.salesMinor)} icon="sales" meta={t('Posted records', displayLanguage)}/><Metric label="CASH & BANK" value={money(k.cashMinor || 0)} icon="banking" meta={t('Cash & bank balance', displayLanguage)}/><Metric label="RECEIVABLES" value={money(k.receivablesMinor)} icon="payments" meta={t('Customer Balances', displayLanguage)}/><Metric label="PAYABLES" value={money(k.payablesMinor)} icon="money" meta={t('Supplier Balances', displayLanguage)}/></div>
    <div className="dashboard-grid">
      <Panel title="Operational exceptions" meta={`${Number(k.pendingApprovals) + low.length} ${t('Items requiring attention', displayLanguage)}`}>
        <div className="attention-list">
          <div className="attention-row"><span className="attention-icon warning"><AppIcon name="pending" size={16}/></span><div><strong>{t('Pending approvals', displayLanguage)}</strong><span>{t('Approval queue', displayLanguage)}</span></div><b>{k.pendingApprovals}</b></div>
          {low.slice(0, 4).map((row: Json) => <div className="attention-row" key={`${row.warehouseId}-${row.itemId}`}><span className="attention-icon danger"><AppIcon name="inventory" size={16}/></span><div><strong>{itemName(row.item)}</strong><span>{referenceName(row.warehouse.name)} · {qty(row.quantityMilli)} {t('On hand', displayLanguage)}</span></div><Status value="CLOSED"/></div>)}
        </div>
      </Panel>
      <Panel title="Recent business activity" meta={t('Recent activity', displayLanguage)}><div className="timeline">{data.activity.slice(0, 6).map((event: Json) => <div className="timeline-row" key={event.id}><i><AppIcon name="history" size={13}/></i><div><strong>{title(event.action)} · {t(event.entityType, displayLanguage)}</strong><span>{t(event.user.name, displayLanguage)} · {t('reference', displayLanguage)} {event.postingReference || event.entityId}</span></div><time>{date(event.createdAt)}</time></div>)}</div></Panel>
      <Panel title="Inventory attention" meta={`${t('Inventory Valuation', displayLanguage)} · ${money(k.inventoryMinor)}`} wide><div className="table-wrap"><table><thead><tr><th>{t('Item', displayLanguage)}</th><th>{t('Warehouse', displayLanguage)}</th><th className="number">{t('On hand', displayLanguage)}</th><th>{t('Signal', displayLanguage)}</th></tr></thead><tbody>{data.lowStock.map((row: Json) => <tr key={`${row.warehouseId}-${row.itemId}`}><td><strong>{row.item.sku}</strong><br/><span className="muted">{itemName(row.item)}</span></td><td>{referenceName(row.warehouse.name)}</td><td className="number">{qty(row.quantityMilli)}</td><td>{BigInt(row.quantityMilli) <= BigInt(row.item.reorderMilli) ? <span className="status CLOSED">{t('Reorder', displayLanguage)}</span> : <span className="status OPEN">{t('Healthy', displayLanguage)}</span>}</td></tr>)}</tbody></table></div></Panel>
    </div>
  </div>;
}
function Metric({ label, value, icon, meta }: { label: string; value: string; icon: IconName; meta?: string }) { return <article className="metric"><span className="metric-icon"><AppIcon name={icon}/></span><label>{t(label, displayLanguage)}</label><strong>{t(value, displayLanguage)}</strong>{meta ? <small>{meta}</small> : null}</article>; }

function DomainOverview({ module, permissions, refs, request, navigate }: { module: string; permissions: readonly string[]; refs: Json; request: (path: string) => Promise<Json>; navigate: (route: string) => void }) {
  const definition = modules.find((entry) => entry.id === module)!;
  const [data, setData] = useState<Json>({ records: [], secondary: null });
  const [busy, setBusy] = useState(true);
  useEffect(() => {
    let active = true;
    const load = async () => {
      setBusy(true);
      try {
        let records: Json[] = [], secondary: Json = null;
        if (module === 'sales' || module === 'purchasing' || module === 'inventory') {
          const types = module === 'sales' ? salesTypes : module === 'purchasing' ? purchaseTypes : inventoryTypes;
          const groups = await Promise.all(types.map((type) => request(`/documents?type=${type}`)));
          records = groups.flat();
        } else if (module === 'accounting') records = await request('/journals');
        else if (module === 'banking') secondary = await request('/banking');
        else if (module === 'admin') records = await request('/audit');
        if (active) setData({ records, secondary });
      } finally {
        if (active) setBusy(false);
      }
    };
    void load();
    return () => { active = false; };
  }, [module, request]);
  if (busy) return <Loading/>;

  const records = data.records as Json[];
  const recent = [...records].sort((a, b) => String(b.createdAt || b.documentDate || b.postingDate).localeCompare(String(a.createdAt || a.documentDate || a.postingDate))).slice(0, 7);
  const quickLinks = definition.children.filter((child) => child.route !== definition.route && canAccess(permissions, child.permission)).slice(0, 6);
  const moduleStats: Record<string, Array<{ label: string; value: string; icon: IconName }>> = {
    sales: [
      { label: 'Total records', value: String(records.length), icon: 'sales' },
      { label: 'Customers', value: String(refs.customers.length), icon: 'item' },
      { label: 'Awaiting approval', value: String(records.filter((row) => row.status === 'SUBMITTED').length), icon: 'pending' },
      { label: 'Posted records', value: String(records.filter((row) => row.status === 'POSTED').length), icon: 'success' },
    ],
    purchasing: [
      { label: 'Total records', value: String(records.length), icon: 'purchases' },
      { label: 'Suppliers', value: String(refs.suppliers.length), icon: 'supplier' },
      { label: 'Awaiting approval', value: String(records.filter((row) => row.status === 'SUBMITTED').length), icon: 'pending' },
      { label: 'Posted records', value: String(records.filter((row) => row.status === 'POSTED').length), icon: 'success' },
    ],
    inventory: [
      { label: 'Items', value: String(refs.items.length), icon: 'item' },
      { label: 'Warehouses', value: String(refs.warehouses.length), icon: 'warehouse' },
      { label: 'Categories', value: String(refs.categories.length), icon: 'inventory' },
      { label: 'Stock Counts', value: String(records.filter((row) => row.type === 'STOCK_COUNT').length), icon: 'checklist' },
    ],
    accounting: [
      { label: 'Journal Entries', value: String(records.length), icon: 'accounting' },
      { label: 'Chart of Accounts', value: String(refs.accounts.length), icon: 'reports' },
      { label: 'Fiscal Periods', value: String(refs.periods.length), icon: 'pending' },
      { label: 'Posted records', value: String(records.filter((row) => row.status === 'POSTED').length), icon: 'success' },
    ],
    banking: [
      { label: 'Cash & Bank Accounts', value: String(data.secondary?.accounts?.length || refs.bankAccounts.length), icon: 'banking' },
      { label: 'Bank Transactions & Transfers', value: String(data.secondary?.transactions?.length || 0), icon: 'payments' },
      { label: 'Bank Statements', value: String(data.secondary?.statements?.length || 0), icon: 'reports' },
      { label: 'Unmatched', value: String(data.secondary?.transactions?.filter((row: Json) => !row.reconciled).length || 0), icon: 'pending' },
    ],
    admin: [
      { label: 'Audit Log', value: String(records.length), icon: 'audit' },
      { label: 'Branches', value: String(refs.branches.length), icon: 'warehouse' },
      { label: 'Fiscal Periods', value: String(refs.periods.length), icon: 'pending' },
      { label: 'System Health', value: t('Healthy', displayLanguage), icon: 'success' },
    ],
  };
  const stats = moduleStats[module] || [];
  return <div className={`page domain-overview ${module}-overview`}>
    <PageHead title={definition.label} subtitle="Business records and workflows organized by domain"/>
    <div className="summary-strip">{stats.map((stat) => <Metric key={stat.label} label={stat.label} value={stat.value} icon={stat.icon}/>)}</div>
    <div className="overview-layout">
      <Panel title="Recent documents" meta={`${recent.length} ${t('records', displayLanguage)}`} wide={module === 'inventory'}>
        {recent.length ? <div className="table-wrap"><table><thead><tr><th>{t('Reference', displayLanguage)}</th><th>{t('Description', displayLanguage)}</th><th>{t('Date', displayLanguage)}</th><th>{t('Status', displayLanguage)}</th><th className="number">{t('Total', displayLanguage)}</th></tr></thead><tbody>{recent.map((row) => <tr key={row.id}><td><strong>{row.number || row.postingReference || row.id}</strong></td><td>{title(row.type || row.sourceType || row.entityType || 'Record')}</td><td>{date(row.documentDate || row.postingDate || row.createdAt)}</td><td>{row.status ? <Status value={row.status}/> : '—'}</td><td className="number">{row.totalMinor === undefined ? '—' : money(row.totalMinor)}</td></tr>)}</tbody></table></div> : <Empty icon="inbox" heading="No matching records" text="Create or post a transaction to populate this overview."/>}
      </Panel>
      <Panel title="Quick access" meta={t('Workspace overview', displayLanguage)}>
        <div className="quick-links">{quickLinks.map((child) => <button key={child.id} onClick={() => navigate(child.route)}><span><strong>{t(child.label, displayLanguage)}</strong><small>{t(baseTitle(child.namespace), displayLanguage)}</small></span><AppIcon name="next" size={15}/></button>)}</div>
      </Panel>
    </div>
  </div>;
}

function MasterDataPage({ kind, permissions, fieldPermissions, refs, request, notify, refreshRefs }: { kind: NonNullable<ReturnType<typeof routeEntry>['child']['masterKind']>; permissions: readonly string[]; fieldPermissions: Json[]; refs: Json; request: (path: string, options?: RequestInit) => Promise<Json>; notify: (message: string, error?: boolean) => void; refreshRefs: () => Promise<void> }) {
  const [search, setSearch] = useState(''), [form, setForm] = useState(false);
  const recordsByKind: Record<string, Json[]> = { customer: refs.customers, supplier: refs.suppliers, item: refs.items, category: refs.categories, unit: refs.units, warehouse: refs.warehouses, bank: refs.bankAccounts, account: refs.accounts };
  const labels: Record<string, string> = { customer: 'Customers', supplier: 'Suppliers', item: 'Items', category: 'Categories', unit: 'Units of Measurement', warehouse: 'Warehouses', bank: 'Cash & Bank Accounts', account: 'Chart of Accounts' };
  const records = recordsByKind[kind] || [];
  const filtered = records.filter((record) => `${record.code || record.sku || ''} ${record.name || ''} ${record.nameAr || ''} ${record.city || ''}`.toLowerCase().includes(search.toLowerCase()));
  const creatable = Boolean(masterCreatePermissions[kind] && canAccess(permissions, masterCreatePermissions[kind]));
  const display = (record: Json) => kind === 'item' ? itemName(record) : referenceName(record.name);
  const detail = (record: Json) => referenceName(record.city || record.barcode || record.currency || record.branch?.name || record.controlType, '—');
  return <div className="page master-page">
    <PageHead title={labels[kind]} subtitle="Search, review and maintain the master records used by operational workflows">{creatable ? <button className="button primary" data-testid={`new-${kind}`} onClick={() => setForm(true)}><AppIcon name="add"/> {t(`New ${baseTitle(kind)}`, displayLanguage)}</button> : null}</PageHead>
    <div className="summary-strip compact"><Metric label="Total records" value={String(records.length)} icon={kind === 'warehouse' ? 'warehouse' : kind === 'bank' ? 'banking' : 'item'}/><Metric label="Active" value={String(records.filter((record) => record.active !== false).length)} icon="success"/></div>
    <section className="data-panel">
      <div className="toolbar"><label className="table-search"><AppIcon name="search" size={15}/><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={t('Search master data…', displayLanguage)}/></label><span className="toolbar-count">{filtered.length} {t('records', displayLanguage)}</span></div>
      {filtered.length ? <div className="table-wrap"><table data-testid="master-data-table"><thead><tr><th>{t(kind === 'item' ? 'SKU' : 'Code', displayLanguage)}</th><th>{t('Name', displayLanguage)}</th><th>{t('Type', displayLanguage)}</th><th>{t('Status', displayLanguage)}</th><th>{t('Details', displayLanguage)}</th></tr></thead><tbody>{filtered.map((record) => <tr key={record.id}><td><strong>{record.code || record.sku}</strong></td><td>{display(record)}</td><td>{title(record.type || record.category?.name || kind)}</td><td><span className={`status ${record.active === false ? 'CLOSED' : 'OPEN'}`}>{t(record.active === false ? 'Inactive' : 'Active', displayLanguage)}</span></td><td className="muted">{detail(record)}</td></tr>)}</tbody></table></div> : <Empty heading="No matching records" text="Adjust the search or filters to view records."/>}
    </section>
    {form ? <MasterForm kind={kind} fieldPermissions={fieldPermissions} refs={refs} request={request} close={() => setForm(false)} saved={async (record) => { setForm(false); await refreshRefs(); notify(`${record.code || record.sku} · ${record.name} created`); }}/> : null}
  </div>;
}

function SystemHealth() {
  return <div className="page system-health-page"><PageHead title="System Health" subtitle="Technical diagnostics are restricted to administrators."/>
    <div className="health-grid"><Metric label="Application services" value={t('Healthy', displayLanguage)} icon="success"/><Metric label="Database service" value={t('Connected', displayLanguage)} icon="banking"/><Metric label="Tenant isolation" value={t('Protected', displayLanguage)} icon="approve"/></div>
    <Panel title="System Health" meta="Administrator only"><div className="health-list"><div><span>PostgreSQL</span><strong>17</strong></div><div><span>{t('Application API', displayLanguage)}</span><strong>NestJS</strong></div><div><span>{t('Data access', displayLanguage)}</span><strong>Prisma</strong></div><div><span>{t('Web application', displayLanguage)}</span><strong>Next.js</strong></div><div><span>{t('Tenant boundary', displayLanguage)}</span><strong>{t('Row-level security', displayLanguage)}</strong></div></div></Panel>
  </div>;
}

function Documents({ module, selectedType, permissions, fieldPermissions, refs, request, notify, refreshRefs, navigate }: { module: string; selectedType: string; permissions: readonly string[]; fieldPermissions: Json[]; refs: Json; request: (path: string, options?: RequestInit) => Promise<Json>; notify: (message: string, error?: boolean) => void; refreshRefs: () => Promise<void>; navigate: (route: string) => void }) {
  const [documents, setDocuments] = useState<Json[]>([]), [busy, setBusy] = useState(true);
  const [form, setForm] = useState(false), [detail, setDetail] = useState<Json>(null), [master, setMaster] = useState('');
  const [search, setSearch] = useState(''), [status, setStatus] = useState('ALL');
  const derived = ['DELIVERY_NOTE', 'SALES_INVOICE', 'SALES_RETURN', 'CREDIT_NOTE', 'GOODS_RECEIPT', 'PURCHASE_BILL', 'PURCHASE_RETURN'].includes(selectedType);
  const isPurchaseRfq = module === 'purchasing' && selectedType === 'PURCHASE_RFQ';
  const routeDefinition = allRoutes.find(({ child }) => child.documentType === selectedType);
  const pageTitle = routeDefinition?.child.label || baseTitle(selectedType);
  const subtitles: Record<string, string> = {
    sales: 'Manage customer documents from quotation through collection and return',
    purchasing: 'Manage supplier sourcing, receiving, billing and returns',
    inventory: 'Record and review controlled movements of stock between locations',
  };
  const load = useCallback(async () => { setBusy(true); try { setDocuments(await request(`/documents?type=${selectedType}`)); } finally { setBusy(false); } }, [request, selectedType]);
  useEffect(() => { load(); }, [load]);
  const openDetail = async (documentId: string) => { try { setDetail(await request(`/documents/${documentId}`)); } catch (error: any) { notify(error.message, true); } };
  const filtered = documents.filter((document) => {
    const matchesStatus = status === 'ALL' || document.status === status;
    const text = `${document.number} ${document.customer?.name || ''} ${document.supplier?.name || ''} ${document.branch?.name || ''}`.toLowerCase();
    return matchesStatus && text.includes(search.trim().toLowerCase());
  });
  const statusOptions = ['ALL', 'DRAFT', 'SUBMITTED', 'APPROVED', 'POSTED', 'REJECTED'];
  const createLabel = isPurchaseRfq ? 'New Request for Quotation' : `New ${baseTitle(selectedType)}`;
  const canCreate = canAccess(permissions, documentPermission(selectedType, 'create'));
  return <div className={`page document-page ${module}-documents`}>
    <PageHead title={pageTitle} subtitle={subtitles[module] || 'Create, approve, convert and post from one business workflow'}>
      {module === 'sales' && canAccess(permissions, 'sales.customer.create') ? <button className="button" data-testid="new-customer" onClick={() => setMaster('customer')}><AppIcon name="add"/> {t('New Customer', displayLanguage)}</button> : null}
      {module === 'purchasing' && canAccess(permissions, 'purchasing.supplier.create') ? <button className="button" data-testid="new-supplier" onClick={() => setMaster('supplier')}><AppIcon name="add"/> {t('New Supplier', displayLanguage)}</button> : null}
      {derived ? <span className="integrity-chip"><AppIcon name="approve" size={14}/>{t('Created from an approved source document', displayLanguage)}</span> : canCreate ? <button className="button primary" data-testid="new-document" onClick={() => setForm(true)}><AppIcon name="add"/> {t(createLabel, displayLanguage)}</button> : null}
    </PageHead>
    <div className="summary-strip compact document-summary">
      <Metric label="Total records" value={String(documents.length)} icon={module === 'sales' ? 'sales' : module === 'purchasing' ? 'purchases' : 'inventory'}/>
      <Metric label="Draft" value={String(documents.filter((document) => document.status === 'DRAFT').length)} icon="checklist"/>
      <Metric label="Awaiting approval" value={String(documents.filter((document) => document.status === 'SUBMITTED').length)} icon="pending"/>
      <Metric label="Posted records" value={String(documents.filter((document) => document.status === 'POSTED').length)} icon="success"/>
    </div>
    <section className="data-panel">
      <div className="toolbar">
        <div className="toolbar-filters">
          <label className="table-search"><AppIcon name="search" size={15}/><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={t('Search by reference or party…', displayLanguage)} aria-label={t('Search documents', displayLanguage)}/></label>
          <label className="filter-select"><span>{t('Status', displayLanguage)}</span><select value={status} onChange={(event) => setStatus(event.target.value)}>{statusOptions.map((option) => <option key={option} value={option}>{t(option === 'ALL' ? 'All statuses' : title(option), displayLanguage)}</option>)}</select></label>
        </div>
        <span className="toolbar-count">{filtered.length} {t('records', displayLanguage)} · {t('newest first', displayLanguage)}</span>
      </div>
      {busy ? <Loading/> : filtered.length ? <div className="table-wrap"><table data-testid="document-table"><thead><tr><th>{t('Document', displayLanguage)}</th><th>{t('Party', displayLanguage)}</th><th>{t('Date', displayLanguage)}</th><th>{t('Status', displayLanguage)}</th><th className="number">{t('Net', displayLanguage)}</th><th className="number">{t('Tax', displayLanguage)}</th><th className="number">{t('Total', displayLanguage)}</th><th>{t('Source', displayLanguage)}</th><th><span className="sr-only">{t('Actions', displayLanguage)}</span></th></tr></thead><tbody>{filtered.map((doc) => <tr key={doc.id}><td><button className="link-button document-number" onClick={() => openDetail(doc.id)}>{doc.number}</button></td><td className="party-cell"><strong>{referenceName(doc.customer?.name || doc.supplier?.name, t('Internal', displayLanguage))}</strong><span>{referenceName(doc.branch.name)}</span></td><td>{date(doc.documentDate)}</td><td><Status value={doc.status}/></td><td className="number">{money(BigInt(doc.subtotalMinor) - BigInt(doc.discountMinor))}</td><td className="number">{money(doc.taxMinor)}</td><td className="number"><strong>{money(doc.totalMinor)}</strong></td><td>{doc.sourceDocument?.number || '—'}</td><td><button className="row-button" onClick={() => openDetail(doc.id)}>{t('View', displayLanguage)}</button></td></tr>)}</tbody></table></div> : <Empty icon={isPurchaseRfq ? 'checklist' : 'inbox'} heading={isPurchaseRfq ? 'No requests for quotation' : search || status !== 'ALL' ? 'No matching records' : `No ${baseTitle(selectedType).toLowerCase()} records`} text={search || status !== 'ALL' ? 'Adjust the search or filters to view records.' : isPurchaseRfq ? 'Create the first request for quotation from this screen.' : 'Create the first one from this screen.'}/>}
    </section>
    {form ? <DocumentForm type={selectedType} heading={isPurchaseRfq ? 'New Request for Quotation' : undefined} refs={refs} request={request} onClose={() => setForm(false)} onSaved={(doc) => { setForm(false); load(); notify(`${doc.number} saved as draft`); openDetail(doc.id); }}/> : null}
    {master ? <MasterForm kind={master} fieldPermissions={fieldPermissions} refs={refs} request={request} close={() => setMaster('')} saved={async (record) => { setMaster(''); await refreshRefs(); notify(`${record.code} · ${record.name} created`); }}/> : null}
    {detail ? <DocumentDrawer document={detail} permissions={permissions} refs={refs} request={request} notify={notify} close={() => setDetail(null)} reload={async () => { await load(); await openDetail(detail.id); }}/> : null}
  </div>;
}

function DocumentDrawer({ document, permissions, refs, request, notify, close, reload }: { document: Json; permissions: readonly string[]; refs: Json; request: (path: string, options?: RequestInit) => Promise<Json>; notify: (message: string, error?: boolean) => void; close: () => void; reload: () => Promise<void> }) {
  const [busy, setBusy] = useState(''), [conversion, setConversion] = useState('');
  const act = async (action: string, body?: Json) => { setBusy(action); try { const result = await request(`/documents/${document.id}/${action}`, { method: 'POST', ...(body ? { body: JSON.stringify(body) } : {}) }); notify(`${document.number}: ${action} completed${result.accountingEffect ? ` · ${result.accountingEffect}` : ''}`); await reload(); } catch (error: any) { notify(error.message, true); } finally { setBusy(''); } };
  const decide = (action: 'approve' | 'reject') => { const comment = window.prompt(t(`${title(action)} comment`, displayLanguage), t(action === 'approve' ? 'Reviewed and approved' : 'Rejected with correction required', displayLanguage)); if (comment !== null) void act(action, { comment }); };
  const download = async () => { try { const response = await fetch(`${API}/documents/${document.id}/pdf`, { headers: { Authorization: `Bearer ${localStorage.getItem('odin_token')}`, 'Accept-Language': displayLanguage, 'X-Odin-Language': displayLanguage } }); if (!response.ok) throw new Error(localizeError((await response.json()).message, displayLanguage)); const url = URL.createObjectURL(await response.blob()); window.open(url, '_blank'); } catch (error: any) { notify(error.message, true); } };
  const conversions = conversionMap[document.type] || [];
  const allowed = (action: string) => canAccess(permissions, documentPermission(document.type, action));
  return <div className="drawer-layer" onMouseDown={(event) => { if (event.target === event.currentTarget) close(); }}><aside className="drawer"><div className="drawer-head"><div><h2>{document.number}</h2><span className="muted">{title(document.type)} · <Status value={document.status}/></span></div><IconButton icon="close" label={t('Close document', displayLanguage)} className="close-x" onClick={close}/></div><div className="drawer-body">
    <div className="drawer-actions">{document.status === 'DRAFT' && allowed('edit') ? <button className="button primary small" disabled={!!busy} onClick={() => act('submit', { comment: t('Submitted from document workspace', displayLanguage) })}>{t('Submit for approval', displayLanguage)}</button> : null}{document.status === 'SUBMITTED' ? <>{allowed('approve') ? <button className="button success small" disabled={!!busy} onClick={() => decide('approve')}>{t('Approve', displayLanguage)}</button> : null}{allowed('reject') ? <button className="button danger small" disabled={!!busy} onClick={() => decide('reject')}>{t('Reject', displayLanguage)}</button> : null}</> : null}{document.status === 'APPROVED' && allowed('post') ? <button className="button primary small" data-testid="post-document" disabled={!!busy} onClick={() => act('post')}>{t('Post effects', displayLanguage)}</button> : null}{conversions.length > 0 && ['APPROVED','POSTED'].includes(document.status) && allowed('convert') ? conversions.map((target) => <button key={target} className="button secondary small" disabled={!!busy} onClick={() => setConversion(target)}>{t(`Convert to ${title(target)}`, displayLanguage)}</button>) : null}{allowed('print') ? <button className="button small" onClick={download}>{t('Print / PDF', displayLanguage)}</button> : null}</div>
    <div className="chain"><span className="chain-node">{document.sourceDocument?.number || t('Origin', displayLanguage)}</span><span className="chain-arrow"><AppIcon name="next" size={15}/></span><span className="chain-node"><strong>{document.number}</strong></span>{document.targetDocuments.map((target: Json) => <span key={target.id} className="chain-node"><AppIcon name="next" size={15}/> {target.number}</span>)}</div>
    <div className="detail-grid"><Detail label="Party" value={referenceName(document.customer?.name || document.supplier?.name, t('Internal', displayLanguage))}/><Detail label="Posting date" value={date(document.documentDate)}/><Detail label="Branch" value={referenceName(document.branch.name)}/><Detail label="Warehouse" value={document.warehouse?.name ? referenceName(document.warehouse.name) : t('No stock location', displayLanguage)}/><Detail label="Net" value={money(BigInt(document.subtotalMinor)-BigInt(document.discountMinor))}/><Detail label="VAT" value={money(document.taxMinor)}/><Detail label="Total" value={money(document.totalMinor)}/>{document.costMinor !== undefined ? <Detail label="Cost" value={money(document.costMinor)}/> : null}</div>
    <div className="effect-tabs"><span className="status OPEN">{t('Business evidence', displayLanguage)}</span></div>
    <EffectTable title="Document lines" rows={document.lines.map((line: Json) => ({ Item: `${line.item.sku} · ${itemName(line.item)}`, ...(document.type === 'STOCK_COUNT' ? { System: qty(line.systemQuantityMilli), Counted: qty(line.countedQuantityMilli), Variance: `${line.description?.toLowerCase().includes('decrease') ? '−' : '+'}${qty(line.quantityMilli)}` } : { Quantity: qty(line.quantityMilli) }), Price: money(line.unitPriceMinor), Tax: money(line.taxMinor), Total: money(line.totalMinor) }))}/>
    <div className="effect-tabs"><span className="status POSTED">{t('Accounting effect', displayLanguage)}</span></div>{document.journalEntry ? <EffectTable title={`${document.journalEntry.number} · debit equals credit`} rows={document.journalEntry.lines.map((line: Json) => ({ Account: `${line.account.code} ${referenceName(line.account.name)}`, Description: t(line.description, displayLanguage), Debit: money(line.debitMinor), Credit: money(line.creditMinor) }))}/> : <div className="effect-card"><h3>{t('No general-ledger posting', displayLanguage)}</h3><span className="muted">{t(document.accountingEffect, displayLanguage)}. {t('Operational evidence remains linked in the chain.', displayLanguage)}</span></div>}
    <div className="effect-tabs"><span className="status POSTED">{t('Inventory effect', displayLanguage)}</span></div>{document.stockMovements.length ? <EffectTable title="Perpetual inventory movements" rows={document.stockMovements.map((move: Json) => ({ Item: move.item.sku, Warehouse: referenceName(move.warehouse.name), In: qty(move.quantityInMilli), Out: qty(move.quantityOutMilli), ...(move.totalCostMinor !== undefined ? { Cost: money(move.totalCostMinor), RunningValue: money(move.runningValueMinor) } : {}) }))}/> : <div className="effect-card"><h3>{t('No stock movement', displayLanguage)}</h3><span className="muted">{t('This stage does not own custody movement.', displayLanguage)}</span></div>}
    <div className="effect-tabs"><span className="status OPEN">{t('Permission & audit effect', displayLanguage)}</span></div><EffectTable title="Append-only evidence" rows={[...document.approvals.map((event: Json) => ({ When: dateTime(event.createdAt), Actor: t(event.actor.name, displayLanguage), Action: title(event.action), Comment: t(event.comment || '—', displayLanguage), Reference: document.number })), ...document.audit.map((event: Json) => ({ When: dateTime(event.createdAt), Actor: t(event.user.name, displayLanguage), Action: title(event.action), Comment: t('Database audit', displayLanguage), Reference: event.postingReference || event.approvalReference || document.number }))]}/>
  </div></aside>{conversion && <ConversionForm target={conversion} document={document} refs={refs} close={() => setConversion('')} convert={async (body) => { setConversion(''); await act('convert', body); }}/>}</div>;
}

function ConversionForm({ target, document, refs, close, convert }: { target: string; document: Json; refs: Json; close: () => void; convert: (body: Json) => Promise<void> }) {
  const available = document.lines.map((line: Json) => { const consumed = line.targetLines.filter((targetLine: Json) => !['REJECTED', 'CANCELLED'].includes(targetLine.document.status)).reduce((sum: bigint, targetLine: Json) => sum + BigInt(targetLine.quantityMilli), 0n); return { line, remaining: BigInt(line.quantityMilli) - consumed }; }).filter((row: Json) => row.remaining > 0n);
  const [quantities, setQuantities] = useState<Record<string, string>>(Object.fromEntries(available.map((row: Json) => [row.line.id, qty(row.remaining)]))), [warehouseId, setWarehouseId] = useState(document.warehouseId || refs.warehouses[0]?.id || ''), [supplierId, setSupplierId] = useState(document.supplierId || refs.suppliers[0]?.id || ''), [busy, setBusy] = useState(false), [error, setError] = useState('');
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { await convert({ targetType: target, documentDate: today(), warehouseId, supplierId: target === 'PURCHASE_RFQ' ? supplierId : undefined, lines: available.map((row: Json) => ({ sourceLineId: row.line.id, quantity: quantities[row.line.id] })) }); } catch (reason: any) { setError(reason.message); setBusy(false); } };
  return <Modal title={t(`Convert ${document.number} to ${title(target)}`, displayLanguage)} close={close} wide>
    <form onSubmit={submit}>
      <p className="muted">{t('Enter a quantity up to the remaining source quantity. The backend rejects over-conversion and preserves every source-line link.', displayLanguage)}</p>
      <div className="line-editor"><table><thead><tr><th>{t('Item', displayLanguage)}</th><th>{t('Original', displayLanguage)}</th><th>{t('Remaining', displayLanguage)}</th><th>{t('Convert now', displayLanguage)}</th></tr></thead><tbody>{available.map((row: Json) => <tr key={row.line.id}><td>{row.line.item.sku} · {itemName(row.line.item)}</td><td>{qty(row.line.quantityMilli)}</td><td>{qty(row.remaining)}</td><td><input aria-label={t(`Convert ${row.line.item.sku} quantity`, displayLanguage)} value={quantities[row.line.id]} onChange={(event) => setQuantities({ ...quantities, [row.line.id]: event.target.value })} required/></td></tr>)}</tbody></table></div>
      {target === 'PURCHASE_RFQ' && <label className="field">{t('Supplier', displayLanguage)}<select value={supplierId} onChange={(event) => setSupplierId(event.target.value)}>{refs.suppliers.map((supplier: Json) => <option key={supplier.id} value={supplier.id}>{supplier.code} · {referenceName(supplier.name)}</option>)}</select></label>}
      <label className="field">{t('Warehouse', displayLanguage)}<select value={warehouseId} onChange={(event) => setWarehouseId(event.target.value)}>{refs.warehouses.map((warehouse: Json) => <option key={warehouse.id} value={warehouse.id}>{warehouse.code} · {referenceName(warehouse.name)}</option>)}</select></label>
      <p className="form-message">{error || (!available.length ? t('No quantity remains to convert.', displayLanguage) : '')}</p>
      <div className="modal-actions"><button type="button" className="button" onClick={close}>{t('Cancel', displayLanguage)}</button><button data-testid="confirm-conversion" className="button primary" disabled={busy || !available.length || (target === 'PURCHASE_RFQ' && !supplierId)}>{t(busy ? 'Converting…' : 'Create linked draft', displayLanguage)}</button></div>
    </form>
  </Modal>;
}
function Detail({ label, value }: { label: string; value: ReactNode }) { return <div className="detail-field"><span>{t(label, displayLanguage)}</span><strong>{value}</strong></div>; }
function EffectTable({ title: heading, rows }: { title: string; rows: Json[] }) { const columns = rows.length ? Object.keys(rows[0]) : []; return <div className="effect-card"><h3>{t(heading, displayLanguage)}</h3>{rows.length ? <div className="table-wrap"><table><thead><tr>{columns.map((column) => <th key={column}>{t(column, displayLanguage)}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr key={index}>{columns.map((column) => <td key={column}>{t(String(row[column] ?? '—'), displayLanguage)}</td>)}</tr>)}</tbody></table></div> : <span className="muted">{t('No evidence recorded yet.', displayLanguage)}</span>}</div>; }

function Modal({ title: heading, children, close, wide = false }: { title: string; children: ReactNode; close: () => void; wide?: boolean }) { return <div className="modal-layer" onMouseDown={(event) => { if (event.target === event.currentTarget) close(); }}><section className={`modal ${wide ? 'wide' : ''}`}><div className="modal-head"><h2>{t(heading, displayLanguage)}</h2><IconButton icon="close" label={t('Close dialog', displayLanguage)} className="modal-close" onClick={close}/></div><div className="modal-body">{children}</div></section></div>; }

function MasterForm({ kind, fieldPermissions = [], refs, request, close, saved }: { kind: string; fieldPermissions?: Json[]; refs: Json; request: (path: string, options?: RequestInit) => Promise<Json>; close: () => void; saved: (value: Json) => void | Promise<void> }) {
  const [form, setForm] = useState<Json>({ code: '', name: '', city: t('Cairo', displayLanguage), taxNumber: '', email: '', phone: '', address: '', creditLimit: '100000.00', paymentTermsDays: '30', precision: '3', branchId: refs.branches[0]?.id || '', categoryId: refs.categories?.[0]?.id || '', uomId: refs.units?.[0]?.id || '', sku: '', barcode: '', nameAr: '', purchasePrice: '100.00', salePrice: '150.00', taxRatePercent: '14', reorderLevel: '5.000', type: 'BANK', currency: 'EGP', glAccountId: refs.accounts.find((account: Json) => account.code === '1010')?.id || '', bankName: '', accountNumber: '' });
  const [busy, setBusy] = useState(false), [error, setError] = useState('');
  const canEditTax = fieldPermission(fieldPermissions, 'party', 'taxNumber') === 'EDIT';
  const canEditBankDetails = fieldPermission(fieldPermissions, 'bankAccount', 'accountNumber') === 'EDIT';
  const set = (key: string, value: string) => setForm((current: Json) => ({ ...current, [key]: value }));
  const endpoints: Record<string, string> = { customer: 'customers', supplier: 'suppliers', category: 'categories', unit: 'units', warehouse: 'warehouses', item: 'items', bank: 'bank-accounts' };
  const submit = async (event: FormEvent) => { event.preventDefault(); if (busy) return; setBusy(true); setError(''); try { await saved(await request(`/masters/${endpoints[kind]}`, { method: 'POST', body: JSON.stringify(form) })); } catch (reason: any) { setError(reason.message); } finally { setBusy(false); } };
  const common = kind === 'item' ? <label className="field">{t('Name', displayLanguage)}<input data-testid="master-item-name" value={form.name} onChange={(event) => set('name', event.target.value)} required/></label> : <><label className="field">{t('Code', displayLanguage)}<input data-testid={`master-${kind}-code`} value={form.code} onChange={(event) => set('code', event.target.value)} required/></label><label className="field">{t('Name', displayLanguage)}<input data-testid={`master-${kind}-name`} value={form.name} onChange={(event) => set('name', event.target.value)} required/></label></>;
  return <Modal title={t(kind === 'bank' ? 'New Bank account' : `New ${baseTitle(kind)}`, displayLanguage)} close={close} wide={kind === 'item'}><form className="form-grid three" onSubmit={submit}>{common}
    {(kind === 'customer' || kind === 'supplier') && <><label className="field">{t('City', displayLanguage)}<input value={form.city} onChange={(event) => set('city', event.target.value)} required/></label>{canEditTax ? <label className="field">{t('Tax number', displayLanguage)}<input value={form.taxNumber} onChange={(event) => set('taxNumber', event.target.value)}/></label> : null}<label className="field">{t('Email', displayLanguage)}<input type="email" value={form.email} onChange={(event) => set('email', event.target.value)}/></label><label className="field">{t('Phone', displayLanguage)}<input value={form.phone} onChange={(event) => set('phone', event.target.value)}/></label><label className="field">{t('Payment terms (days)', displayLanguage)}<input type="number" min="0" value={form.paymentTermsDays} onChange={(event) => set('paymentTermsDays', event.target.value)} required/></label>{kind === 'customer' && <label className="field">{t('Credit limit', displayLanguage)}<input value={form.creditLimit} onChange={(event) => set('creditLimit', event.target.value)} required/></label>}<label className="field full">{t('Address', displayLanguage)}<input value={form.address} onChange={(event) => set('address', event.target.value)}/></label></>}
    {kind === 'unit' && <label className="field">{t('Decimal precision', displayLanguage)}<input type="number" min="0" max="6" value={form.precision} onChange={(event) => set('precision', event.target.value)} required/></label>}
    {kind === 'warehouse' && <label className="field">{t('Branch', displayLanguage)}<select value={form.branchId} onChange={(event) => set('branchId', event.target.value)}>{refs.branches.map((branch: Json) => <option key={branch.id} value={branch.id}>{branch.code} · {referenceName(branch.name)}</option>)}</select></label>}
    {kind === 'item' && <><label className="field">{t('SKU', displayLanguage)}<input data-testid="master-item-sku" value={form.sku} onChange={(event) => set('sku', event.target.value)} required/></label><label className="field">{t('Barcode', displayLanguage)}<input value={form.barcode} onChange={(event) => set('barcode', event.target.value)} required/></label><label className="field">{t('Arabic name', displayLanguage)}<input value={form.nameAr} onChange={(event) => set('nameAr', event.target.value)} placeholder={t('Defaults to English name', displayLanguage)}/></label><label className="field">{t('Category', displayLanguage)}<select value={form.categoryId} onChange={(event) => set('categoryId', event.target.value)}>{(refs.categories || []).map((category: Json) => <option key={category.id} value={category.id}>{category.code} · {referenceName(category.name)}</option>)}</select></label><label className="field">{t('Unit of measure', displayLanguage)}<select value={form.uomId} onChange={(event) => set('uomId', event.target.value)}>{(refs.units || []).map((unit: Json) => <option key={unit.id} value={unit.id}>{unit.code} · {referenceName(unit.name)}</option>)}</select></label><label className="field">{t('Purchase price', displayLanguage)}<input value={form.purchasePrice} onChange={(event) => set('purchasePrice', event.target.value)} required/></label><label className="field">{t('Sales price', displayLanguage)}<input value={form.salePrice} onChange={(event) => set('salePrice', event.target.value)} required/></label><label className="field">{t('VAT %', displayLanguage)}<input value={form.taxRatePercent} onChange={(event) => set('taxRatePercent', event.target.value)} required/></label><label className="field">{t('Reorder level', displayLanguage)}<input value={form.reorderLevel} onChange={(event) => set('reorderLevel', event.target.value)} required/></label></>}
    {kind === 'bank' && <><label className="field">{t('Type', displayLanguage)}<select value={form.type} onChange={(event) => set('type', event.target.value)}><option value="CASH">{t('Cash', displayLanguage)}</option><option value="BANK">{t('Bank', displayLanguage)}</option><option value="CARD_CLEARING">{t('Card clearing', displayLanguage)}</option></select></label><label className="field">{t('Currency', displayLanguage)}<input value={form.currency} onChange={(event) => set('currency', event.target.value)} required/></label><label className="field">{t('GL asset account', displayLanguage)}<select value={form.glAccountId} onChange={(event) => set('glAccountId', event.target.value)}>{refs.accounts.filter((account: Json) => account.type === 'ASSET' && account.postingAllowed && !account.controlType).map((account: Json) => <option key={account.id} value={account.id}>{account.code} · {referenceName(account.name)}</option>)}</select></label><label className="field">{t('Bank name', displayLanguage)}<input value={form.bankName} onChange={(event) => set('bankName', event.target.value)}/></label>{canEditBankDetails ? <label className="field">{t('Account number', displayLanguage)}<input value={form.accountNumber} onChange={(event) => set('accountNumber', event.target.value)}/></label> : null}</>}
    <p className="form-message full" role="alert">{error}</p><div className="modal-actions full"><button type="button" className="button" onClick={close}>{t('Cancel', displayLanguage)}</button><button data-testid={`save-${kind}`} className="button primary" disabled={busy}>{t(busy ? 'Saving…' : `Create ${baseTitle(kind)}`, displayLanguage)}</button></div>
  </form></Modal>;
}

function DocumentForm({ type, heading, refs, request, onClose, onSaved }: { type: string; heading?: string; refs: Json; request: (path: string, options?: RequestInit) => Promise<Json>; onClose: () => void; onSaved: (document: Json) => void }) {
  const purchase = purchaseTypes.includes(type), inventory = inventoryTypes.includes(type);
  const needsSupplier = purchase && type !== 'PURCHASE_REQUEST';
  const defaultBranch = refs.branches.find((branch: Json) => branch.code === 'CAI') || refs.branches[0];
  const defaultWarehouse = refs.warehouses.find((warehouse: Json) => warehouse.code === 'CAI-MAIN') || refs.warehouses.find((warehouse: Json) => warehouse.branchId === defaultBranch?.id) || refs.warehouses[0];
  const destinationWarehouse = refs.warehouses.find((warehouse: Json) => warehouse.code === 'CAI-RTL') || refs.warehouses.find((warehouse: Json) => warehouse.id !== defaultWarehouse?.id) || refs.warehouses[1];
  const [fields, setFields] = useState({ branchId: defaultBranch?.id || '', warehouseId: defaultWarehouse?.id || '', destinationWarehouseId: destinationWarehouse?.id || '', partyId: (needsSupplier ? refs.suppliers[0]?.id : purchase ? '' : refs.customers[0]?.id) || '', documentDate: today(), dueDate: '', currency: 'EGP', exchangeRate: '1.000000', priceList: t(purchase ? 'Standard purchase' : 'Standard sales', displayLanguage), taxMode: 'EXCLUSIVE', paymentTerms: t('30 days', displayLanguage), salesperson: '', attachments: '', notes: '' });
  const [lines, setLines] = useState([{ itemId: refs.items[0]?.id || '', quantity: '1.000', unitPrice: '', discount: '0.00', description: '' }]);
  const [error, setError] = useState(''), [busy, setBusy] = useState(false);
  const updateLine = (index: number, key: string, value: string) => setLines((current) => current.map((line, row) => row === index ? { ...line, [key]: value } : line));
  const summary = useMemo(() => lines.reduce((total, line) => { const item = refs.items.find((entry: Json) => entry.id === line.itemId); const defaultPrice = purchase ? Number(item?.purchasePriceMinor || 0) / 100 : Number(item?.salePriceMinor || 0) / 100; const charged = Number(line.quantity || 0) * Number(line.unitPrice || defaultPrice) - Number(line.discount || 0); const rate = Number(item?.taxRateBps || 0) / 10000; const net = fields.taxMode === 'INCLUSIVE' ? charged / (1 + rate) : charged; const tax = fields.taxMode === 'EXEMPT' ? 0 : fields.taxMode === 'INCLUSIVE' ? charged - net : net * rate; return { net: total.net + net, tax: total.tax + tax }; }, { net: 0, tax: 0 }), [lines, refs.items, purchase, fields.taxMode]);
  const save = async (event: FormEvent) => { event.preventDefault(); if (busy) return; setBusy(true); setError(''); try { const body: Json = { type, branchId: fields.branchId, warehouseId: fields.warehouseId || undefined, destinationWarehouseId: type === 'WAREHOUSE_TRANSFER' ? fields.destinationWarehouseId : undefined, customerId: !purchase && !inventory ? fields.partyId : undefined, supplierId: needsSupplier ? fields.partyId : undefined, documentDate: fields.documentDate, dueDate: fields.dueDate || undefined, currency: fields.currency, exchangeRate: fields.exchangeRate, priceList: fields.priceList, taxMode: fields.taxMode, paymentTerms: fields.paymentTerms, salesperson: fields.salesperson, attachments: fields.attachments.split('\n').map((value) => value.trim()).filter(Boolean), notes: fields.notes, lines: lines.map((line) => ({ ...line, ...(type === 'STOCK_COUNT' ? { countedQuantity: line.quantity } : {}), unitPrice: line.unitPrice || undefined })) }; onSaved(await request('/documents', { method: 'POST', body: JSON.stringify(body) })); } catch (reason: any) { setError(reason.message); } finally { setBusy(false); } };
  return <Modal title={t(heading || `New ${baseTitle(type)}`, displayLanguage)} close={onClose} wide><form className="form-grid three" onSubmit={save}>
    <label className="field">{t('Branch', displayLanguage)}<select value={fields.branchId} onChange={(event) => setFields({ ...fields, branchId: event.target.value })}>{refs.branches.map((branch: Json) => <option key={branch.id} value={branch.id}>{branch.code} · {referenceName(branch.name)}</option>)}</select></label>
    <label className="field">{t('Document date', displayLanguage)}<input type="date" value={fields.documentDate} onChange={(event) => setFields({ ...fields, documentDate: event.target.value })} required/></label>
    <label className="field">{t('Due date', displayLanguage)}<input type="date" value={fields.dueDate} onChange={(event) => setFields({ ...fields, dueDate: event.target.value })}/></label>
    {(!purchase && !inventory || needsSupplier) && <label className="field">{t(needsSupplier ? 'Supplier' : 'Customer', displayLanguage)}<select value={fields.partyId} onChange={(event) => setFields({ ...fields, partyId: event.target.value })}>{(needsSupplier ? refs.suppliers : refs.customers).map((party: Json) => <option key={party.id} value={party.id}>{party.code} · {referenceName(party.name)}</option>)}</select></label>}
    <label className="field">{t('Warehouse', displayLanguage)}<select value={fields.warehouseId} onChange={(event) => setFields({ ...fields, warehouseId: event.target.value })}><option value="">{t('No stock location', displayLanguage)}</option>{refs.warehouses.map((warehouse: Json) => <option key={warehouse.id} value={warehouse.id}>{warehouse.code} · {referenceName(warehouse.name)}</option>)}</select></label>
    {type === 'WAREHOUSE_TRANSFER' && <label className="field">{t('Destination warehouse', displayLanguage)}<select value={fields.destinationWarehouseId} onChange={(event) => setFields({ ...fields, destinationWarehouseId: event.target.value })}>{refs.warehouses.map((warehouse: Json) => <option key={warehouse.id} value={warehouse.id}>{warehouse.code} · {referenceName(warehouse.name)}</option>)}</select></label>}
    {!inventory && <><label className="field">{t('Currency', displayLanguage)}<input value={fields.currency} onChange={(event) => setFields({ ...fields, currency: event.target.value })} required/></label><label className="field">{t('Exchange rate', displayLanguage)}<input value={fields.exchangeRate} onChange={(event) => setFields({ ...fields, exchangeRate: event.target.value })} required/></label><label className="field">{t('Price list', displayLanguage)}<input value={fields.priceList} onChange={(event) => setFields({ ...fields, priceList: event.target.value })}/></label><label className="field">{t('Tax mode', displayLanguage)}<select value={fields.taxMode} onChange={(event) => setFields({ ...fields, taxMode: event.target.value })}><option value="EXCLUSIVE">{t('Tax exclusive', displayLanguage)}</option><option value="INCLUSIVE">{t('Tax inclusive', displayLanguage)}</option><option value="EXEMPT">{t('Tax exempt', displayLanguage)}</option></select></label><label className="field">{t('Payment terms', displayLanguage)}<input value={fields.paymentTerms} onChange={(event) => setFields({ ...fields, paymentTerms: event.target.value })}/></label><label className="field">{t('Salesperson / buyer', displayLanguage)}<input value={fields.salesperson} onChange={(event) => setFields({ ...fields, salesperson: event.target.value })}/></label><label className="field full">{t('Attachment references', displayLanguage)}<textarea value={fields.attachments} onChange={(event) => setFields({ ...fields, attachments: event.target.value })} placeholder={t('One file or URL reference per line', displayLanguage)}/></label></>}
    <label className="field full">{t('Notes', displayLanguage)}<textarea value={fields.notes} onChange={(event) => setFields({ ...fields, notes: event.target.value })} placeholder={t('Commercial terms, reason, or receiving notes', displayLanguage)}/></label>
    <div className="line-editor"><table><thead><tr><th>{t('Item', displayLanguage)}</th><th>{t(type === 'STOCK_COUNT' ? 'Counted quantity' : 'Quantity', displayLanguage)}</th><th>{t('Unit price', displayLanguage)}</th><th>{t('Discount', displayLanguage)}</th><th>{t('Description / adjustment direction', displayLanguage)}</th><th></th></tr></thead><tbody>{lines.map((line, index) => <tr key={index}><td><select className="item-select" value={line.itemId} onChange={(event) => updateLine(index, 'itemId', event.target.value)}>{refs.items.map((item: Json) => <option key={item.id} value={item.id}>{item.sku} · {itemName(item)}</option>)}</select></td><td><input aria-label={`${t('Line', displayLanguage)} ${index + 1} ${t('quantity', displayLanguage)}`} value={line.quantity} onChange={(event) => updateLine(index, 'quantity', event.target.value)} required/></td><td><input aria-label={`${t('Line', displayLanguage)} ${index + 1} ${t('unit price', displayLanguage)}`} value={line.unitPrice} placeholder={t('Master price', displayLanguage)} onChange={(event) => updateLine(index, 'unitPrice', event.target.value)}/></td><td><input value={line.discount} onChange={(event) => updateLine(index, 'discount', event.target.value)}/></td><td>{type === 'INVENTORY_ADJUSTMENT' ? <select value={line.description || 'Increase'} onChange={(event) => updateLine(index, 'description', event.target.value)}><option value="Increase">{t('Increase', displayLanguage)}</option><option value="Decrease">{t('Decrease', displayLanguage)}</option></select> : <input value={line.description} placeholder={t(type === 'STOCK_COUNT' ? 'Variance direction is calculated' : 'Optional line note', displayLanguage)} readOnly={type === 'STOCK_COUNT'} onChange={(event) => updateLine(index, 'description', event.target.value)}/>}</td><td><IconButton icon="remove" label={t('Remove line', displayLanguage)} className="remove-line" onClick={() => setLines((current) => current.filter((_, row) => row !== index))}/></td></tr>)}</tbody></table></div>
    <div className="line-actions"><button type="button" className="button small" onClick={() => setLines((current) => [...current, { itemId: refs.items[0]?.id || '', quantity: '1.000', unitPrice: '', discount: '0.00', description: '' }])}><AppIcon name="add"/> {t('Add line', displayLanguage)}</button></div>
    <div className="summary-box"><div><span>{t('NET', displayLanguage)}</span><strong>{money(BigInt(Math.round(summary.net * 100)))}</strong></div><div><span>{t('VAT', displayLanguage)}</span><strong>{money(BigInt(Math.round(summary.tax * 100)))}</strong></div><div><span>{t('DOCUMENT TOTAL', displayLanguage)}</span><strong>{money(BigInt(Math.round((summary.net + summary.tax) * 100)))}</strong></div></div>
    <p className="form-message" role="alert">{error}</p><div className="modal-actions full"><button type="button" className="button" onClick={onClose}>{t('Cancel', displayLanguage)}</button><button data-testid="save-document" className="button primary" disabled={busy || !lines.length}>{t(busy ? 'Saving atomically…' : 'Save draft', displayLanguage)}</button></div>
  </form></Modal>;
}

function Approvals({ pageTitle, request, notify }: { pageTitle: string; request: (path: string, options?: RequestInit) => Promise<Json>; notify: (message: string, error?: boolean) => void }) {
  const [data, setData] = useState<Json>(null), [busy, setBusy] = useState('');
  const load = useCallback(() => request('/approvals').then(setData), [request]); useEffect(() => { load(); }, [load]);
  const act = async (entity: 'documents' | 'journals', id: string, action: string) => { const comment = window.prompt(t(`${title(action)} comment`, displayLanguage), t(action === 'approve' ? 'Reviewed in approval inbox' : 'Correction required', displayLanguage)); if (comment === null) return; setBusy(`${entity}-${id}`); try { await request(`/${entity}/${id}/${action}`, { method: 'POST', body: JSON.stringify({ comment }) }); notify(action === 'approve' ? 'Approval completed' : 'Rejection completed'); await load(); } catch (error: any) { notify(error.message, true); } finally { setBusy(''); } };
  if (!data) return <Loading/>;
  const total = data.documents.length + data.journals.length;
  return <div className="page"><PageHead title={pageTitle} subtitle="Maker-checker decisions with actor and timestamp evidence"><span className="status SUBMITTED">{t(`${total} waiting`, displayLanguage)}</span></PageHead><div className="split-view"><Panel title="Submitted documents" meta={`${data.documents.length} records`}>{data.documents.length ? <table><thead><tr><th>{t('Reference / contents', displayLanguage)}</th><th>{t('Maker', displayLanguage)}</th><th className="number">{t('Amount', displayLanguage)}</th><th>{t('Decision', displayLanguage)}</th></tr></thead><tbody>{data.documents.map((doc: Json) => <tr key={doc.id}><td><details><summary><strong>{doc.number}</strong> · {title(doc.type)}</summary><span className="muted">{referenceName(doc.customer?.name || doc.supplier?.name, t('Internal', displayLanguage))} · {doc.lines.map((line: Json) => `${line.item.sku} × ${qty(line.quantityMilli)}`).join(', ')}</span></details></td><td>{t(doc.submittedBy?.name, displayLanguage)}<br/><span className="muted">{dateTime(doc.submittedAt)} · {t('step 1', displayLanguage)}</span></td><td className="number">{money(doc.totalMinor)}</td><td><button className="button success small" disabled={!!busy} onClick={() => act('documents', doc.id, 'approve')}>{t('Approve', displayLanguage)}</button> <button className="button danger small" disabled={!!busy} onClick={() => act('documents', doc.id, 'reject')}>{t('Reject', displayLanguage)}</button></td></tr>)}</tbody></table> : <Empty heading="Document inbox clear" text="Submitted business documents will appear here."/>}</Panel>
  <Panel title="Submitted journals" meta={`${data.journals.length} records`}>{data.journals.length ? <table><thead><tr><th>{t('Journal', displayLanguage)}</th><th>{t('Maker', displayLanguage)}</th><th>{t('Description', displayLanguage)}</th><th>{t('Decision', displayLanguage)}</th></tr></thead><tbody>{data.journals.map((journal: Json) => <tr key={journal.id}><td><strong>{journal.number}</strong></td><td>{t(journal.submittedBy?.name, displayLanguage)}</td><td>{t(journal.description, displayLanguage)}</td><td><button className="button success small" disabled={!!busy} onClick={() => act('journals', journal.id, 'approve')}>{t('Approve', displayLanguage)}</button> <button className="button danger small" disabled={!!busy} onClick={() => act('journals', journal.id, 'reject')}>{t('Reject', displayLanguage)}</button></td></tr>)}</tbody></table> : <Empty heading="Journal inbox clear" text="Submitted manual journals will appear here."/>}</Panel></div></div>;
}

function Accounting({ pageTitle, screenId, refs, request, notify, refreshRefs, canWrite, canApprove, canPost, canManagePeriods }: { pageTitle: string; screenId: string; refs: Json; request: (path: string, options?: RequestInit) => Promise<Json>; notify: (message: string, error?: boolean) => void; refreshRefs: () => Promise<void>; canWrite: boolean; canApprove: boolean; canPost: boolean; canManagePeriods: boolean }) {
  const [journals, setJournals] = useState<Json[]>([]), [modal, setModal] = useState(false), [periodModal, setPeriodModal] = useState(false), [busy, setBusy] = useState('');
  const load = useCallback(() => request('/journals').then(setJournals), [request]); useEffect(() => { load(); }, [load]);
  const act = async (journal: Json, action: string) => { let body: Json | undefined; if (action === 'reverse/create') { const reason = window.prompt(t('Reversal reason', displayLanguage), t('Correction entered from general ledger', displayLanguage)); if (!reason) return; const postingDate = window.prompt(t('Open reversal date (YYYY-MM-DD)', displayLanguage), today()); if (!postingDate) return; body = { postingDate, reason }; } setBusy(journal.id); try { await request(`/journals/${journal.id}/${action}`, { method: 'POST', ...(body ? { body: JSON.stringify(body) } : {}) }); notify(`${journal.number}: ${action} completed`); await load(); } catch (error: any) { notify(error.message, true); } finally { setBusy(''); } };
  const edit = async (journal: Json) => { const description = window.prompt(t(`Edit ${journal.number} description`, displayLanguage), t(journal.description, displayLanguage)); if (!description) return; try { await request(`/journals/${journal.id}`, { method: 'PATCH', body: JSON.stringify({ description }) }); notify(`${journal.number} draft updated`); load(); } catch (error: any) { notify(error.message, true); } };
  const showPeriods = screenId === 'periods';
  return <div className="page"><PageHead title={pageTitle} subtitle="Balanced journals, maker-checker approval, period control and linked reversals">{showPeriods && canManagePeriods && <button className="button primary" onClick={() => setPeriodModal(true)}><AppIcon name="add"/> {t('Fiscal period', displayLanguage)}</button>}{!showPeriods && canWrite && <button className="button primary" onClick={() => setModal(true)}><AppIcon name="add"/> {t('Manual journal', displayLanguage)}</button>}</PageHead>
    {!showPeriods && <div className="proof-strip"><div className="proof"><i><AppIcon name="success"/></i><div><strong>{t('POSTED ENTRIES IMMUTABLE', displayLanguage)}</strong><span>{t('Corrections require linked reversal journals', displayLanguage)}</span></div></div><div className="proof"><i><AppIcon name="success"/></i><div><strong>{t('CONTROL ACCOUNTS PROTECTED', displayLanguage)}</strong><span>{t('Manual AR, AP and inventory posting is blocked', displayLanguage)}</span></div></div><div className="proof"><i><AppIcon name="success"/></i><div><strong>{t('PERIOD CONTROL', displayLanguage)}</strong><span>{t('Closed dates reject posting at service and DB boundaries', displayLanguage)}</span></div></div></div>}
    {!showPeriods && <div className="data-panel"><div className="table-wrap"><table><thead><tr><th>{t('Journal', displayLanguage)}</th><th>{t('Date', displayLanguage)}</th><th>{t('Source', displayLanguage)}</th><th>{t('Description / lines', displayLanguage)}</th><th>{t('Status', displayLanguage)}</th><th className="number">{t('Debit', displayLanguage)}</th><th className="number">{t('Credit', displayLanguage)}</th><th>{t('Actions', displayLanguage)}</th></tr></thead><tbody>{journals.map((journal) => { const debit = journal.lines.reduce((sum: bigint, line: Json) => sum + BigInt(line.debitMinor), 0n), credit = journal.lines.reduce((sum: bigint, line: Json) => sum + BigInt(line.creditMinor), 0n); return <tr key={journal.id}><td><strong>{journal.number}</strong>{journal.reversesEntryId && <><br/><span className="muted">{t(`Reverses entry #${journal.reversesEntryId}`, displayLanguage)}</span></>}</td><td>{date(journal.postingDate)}</td><td>{journal.sourceNumber}</td><td><details><summary>{t(journal.description, displayLanguage)}</summary>{journal.lines.map((line: Json) => <div key={line.id} className="muted">{line.account.code} {referenceName(line.account.name)} · {t('Dr', displayLanguage)} {money(line.debitMinor)} · {t('Cr', displayLanguage)} {money(line.creditMinor)}</div>)}</details></td><td><Status value={journal.status}/></td><td className="number">{money(debit)}</td><td className="number">{money(credit)}</td><td>{canWrite && <button className="row-button" disabled={!!busy} onClick={() => edit(journal)}>{t('Edit', displayLanguage)}</button>} {journal.status === 'DRAFT' && canWrite && <button className="row-button" disabled={!!busy} onClick={() => act(journal, 'submit')}>{t('Submit', displayLanguage)}</button>}{journal.status === 'SUBMITTED' && canApprove && <button className="row-button" disabled={!!busy} onClick={() => act(journal, 'approve')}>{t('Approve', displayLanguage)}</button>}{journal.status === 'APPROVED' && canPost && <button className="row-button" disabled={!!busy} onClick={() => act(journal, 'post')}>{t('Post', displayLanguage)}</button>}{journal.status === 'POSTED' && !journal.reversesEntryId && canPost && <button className="row-button" disabled={!!busy} onClick={() => act(journal, 'reverse/create')}>{t('Reverse', displayLanguage)}</button>}</td></tr>; })}</tbody></table></div></div>}
    {showPeriods && <div className="data-panel"><Panel title="Fiscal periods" meta={canManagePeriods ? 'Administrator control' : 'Read-only period calendar'}><table><thead><tr><th>{t('Period', displayLanguage)}</th><th>{t('Status', displayLanguage)}</th><th>{t('Start', displayLanguage)}</th><th>{t('End', displayLanguage)}</th><th>{t('Control', displayLanguage)}</th></tr></thead><tbody>{refs.periods.slice(0, 12).map((period: Json) => <tr key={period.id}><td><strong>{monthYear(period.startDate)}</strong></td><td><Status value={period.status}/></td><td>{date(period.startDate)}</td><td>{date(period.endDate)}</td><td>{canManagePeriods ? <button className="row-button" onClick={async () => { try { await request(`/periods/${period.id}`, { method: 'PATCH', body: JSON.stringify({ status: period.status === 'OPEN' ? 'CLOSED' : 'OPEN' }) }); await refreshRefs(); notify(`${monthYear(period.startDate)} is now ${period.status === 'OPEN' ? 'closed' : 'open'}`); } catch (error: any) { notify(error.message, true); } }}>{t(period.status === 'OPEN' ? 'Close' : 'Open', displayLanguage)}</button> : <span className="muted">{t('No permission', displayLanguage)}</span>}</td></tr>)}</tbody></table></Panel></div>}
    {modal && <JournalForm refs={refs} request={request} close={() => setModal(false)} saved={(journal) => { setModal(false); load(); notify(`${journal.number} created and balanced`); }}/>} {periodModal && <PeriodForm request={request} close={() => setPeriodModal(false)} saved={async (period) => { setPeriodModal(false); await refreshRefs(); notify(`${period.name} created open`); }}/>}</div>;
}

function PeriodForm({ request, close, saved }: { request: (path: string, options?: RequestInit) => Promise<Json>; close: () => void; saved: (period: Json) => void | Promise<void> }) {
  const [form, setForm] = useState({ year: '2027', month: '1', name: monthYear('2027-01-01'), startDate: '2027-01-01', endDate: '2027-01-31' }), [busy, setBusy] = useState(false), [error, setError] = useState('');
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { await saved(await request('/periods', { method: 'POST', body: JSON.stringify(form) })); } catch (reason: any) { setError(reason.message); } finally { setBusy(false); } };
  return <Modal title="Create fiscal period" close={close}><form className="form-grid" onSubmit={submit}><label className="field">{t('Year', displayLanguage)}<input value={form.year} onChange={(event) => setForm({ ...form, year: event.target.value })} required/></label><label className="field">{t('Month', displayLanguage)}<input value={form.month} onChange={(event) => setForm({ ...form, month: event.target.value })} required/></label><label className="field full">{t('Name', displayLanguage)}<input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required/></label><label className="field">{t('Start date', displayLanguage)}<input type="date" value={form.startDate} onChange={(event) => setForm({ ...form, startDate: event.target.value })} required/></label><label className="field">{t('End date', displayLanguage)}<input type="date" value={form.endDate} onChange={(event) => setForm({ ...form, endDate: event.target.value })} required/></label><p className="form-message">{error}</p><div className="modal-actions full"><button type="button" className="button" onClick={close}>{t('Cancel', displayLanguage)}</button><button className="button primary" disabled={busy}>{t(busy ? 'Creating…' : 'Create open period', displayLanguage)}</button></div></form></Modal>;
}

function JournalForm({ refs, request, close, saved }: { refs: Json; request: (path: string, options?: RequestInit) => Promise<Json>; close: () => void; saved: (journal: Json) => void }) {
  const postingAccounts = refs.accounts.filter((account: Json) => account.postingAllowed && !account.controlType);
  const [description, setDescription] = useState(t('Accrual adjustment', displayLanguage)), [postingDate, setPostingDate] = useState(today()), [branchId, setBranchId] = useState(refs.branches.find((branch: Json) => branch.code === 'CAI')?.id || refs.branches[0]?.id || ''), [busy, setBusy] = useState(false), [error, setError] = useState('');
  const [lines, setLines] = useState([{ accountId: postingAccounts[0]?.id || '', debit: '100.00', credit: '0.00', description: t('Debit line', displayLanguage), costCenter: 'HEAD-OFFICE' }, { accountId: postingAccounts[1]?.id || '', debit: '0.00', credit: '100.00', description: t('Credit line', displayLanguage), costCenter: 'HEAD-OFFICE' }]);
  const update = (index: number, key: string, value: string) => setLines((current) => current.map((line, row) => row === index ? { ...line, [key]: value } : line));
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { saved(await request('/journals', { method: 'POST', body: JSON.stringify({ branchId, postingDate, description, lines }) })); } catch (reason: any) { setError(reason.message); } finally { setBusy(false); } };
  return <Modal title="New manual journal" close={close} wide><form className="form-grid" onSubmit={submit}><label className="field">{t('Branch', displayLanguage)}<select value={branchId} onChange={(event) => setBranchId(event.target.value)}>{refs.branches.map((branch: Json) => <option key={branch.id} value={branch.id}>{branch.code} · {referenceName(branch.name)}</option>)}</select></label><label className="field">{t('Posting date', displayLanguage)}<input type="date" value={postingDate} onChange={(event) => setPostingDate(event.target.value)}/></label><label className="field full">{t('Description', displayLanguage)}<input value={description} onChange={(event) => setDescription(event.target.value)}/></label><div className="line-editor"><table><thead><tr><th>{t('Posting account', displayLanguage)}</th><th>{t('Description', displayLanguage)}</th><th>{t('Cost center', displayLanguage)}</th><th>{t('Debit', displayLanguage)}</th><th>{t('Credit', displayLanguage)}</th><th></th></tr></thead><tbody>{lines.map((line, index) => <tr key={index}><td><select className="item-select" value={line.accountId} onChange={(event) => update(index, 'accountId', event.target.value)}>{postingAccounts.map((account: Json) => <option key={account.id} value={account.id}>{account.code} · {referenceName(account.name)}</option>)}</select></td><td><input value={line.description} onChange={(event) => update(index, 'description', event.target.value)}/></td><td><input value={line.costCenter} onChange={(event) => update(index, 'costCenter', event.target.value)}/></td><td><input value={line.debit} onChange={(event) => update(index, 'debit', event.target.value)}/></td><td><input value={line.credit} onChange={(event) => update(index, 'credit', event.target.value)}/></td><td><IconButton icon="remove" label={t('Remove line', displayLanguage)} className="remove-line" onClick={() => setLines((rows) => rows.filter((_, row) => row !== index))}/></td></tr>)}</tbody></table></div><div className="line-actions"><button type="button" className="button small" onClick={() => setLines((rows) => [...rows, { accountId: postingAccounts[0]?.id || '', debit: '0.00', credit: '0.00', description: t('Journal line', displayLanguage), costCenter: 'HEAD-OFFICE' }])}><AppIcon name="add"/> {t('Add line', displayLanguage)}</button></div><p className="form-message">{error}</p><div className="modal-actions full"><button type="button" className="button" onClick={close}>{t('Cancel', displayLanguage)}</button><button className="button primary" disabled={busy || lines.length < 2}>{t(busy ? 'Validating balance…' : 'Create balanced draft', displayLanguage)}</button></div></form></Modal>;
}

function Payments({ pageTitle, refs, request, notify, canWrite }: { pageTitle: string; refs: Json; request: (path: string, options?: RequestInit) => Promise<Json>; notify: (message: string, error?: boolean) => void; canWrite: boolean }) {
  const [payments, setPayments] = useState<Json[]>([]), [modal, setModal] = useState(false);
  const load = useCallback(() => request('/payments').then(setPayments), [request]); useEffect(() => { load(); }, [load]);
  return <div className="page"><PageHead title={pageTitle} subtitle="Allocate cash or bank movements to posted invoices and bills">{canWrite && <button className="button primary" onClick={() => setModal(true)}><AppIcon name="add"/> {t('Allocate payment', displayLanguage)}</button>}</PageHead>
    <div className="data-panel">{payments.length ? <div className="table-wrap"><table><thead><tr><th>{t('Number', displayLanguage)}</th><th>{t('Kind', displayLanguage)}</th><th>{t('Party', displayLanguage)}</th><th>{t('Bank / cash', displayLanguage)}</th><th>{t('Date', displayLanguage)}</th><th className="number">{t('Amount', displayLanguage)}</th><th>{t('Allocation', displayLanguage)}</th><th>{t('Journal', displayLanguage)}</th></tr></thead><tbody>{payments.map((payment) => <tr key={payment.id}><td><strong>{payment.number}</strong></td><td><Status value={payment.kind}/></td><td>{referenceName(payment.customer?.name || payment.supplier?.name)}</td><td>{referenceName(payment.bankAccount.name)}</td><td>{date(payment.postingDate)}</td><td className="number">{money(payment.amountMinor)}</td><td>{payment.allocations.map((allocation: Json) => `${allocation.document.number}: ${money(allocation.amountMinor)}`).join(', ')}</td><td>{payment.journalEntry.number}</td></tr>)}</tbody></table></div> : <Empty heading="No allocated payments" text="Use the button above to settle a posted invoice or purchase bill."/>}</div>
    {modal && <PaymentForm refs={refs} request={request} close={() => setModal(false)} saved={(payment) => { setModal(false); load(); notify(`${payment.number} posted, allocated, and journaled`); }}/>}</div>;
}

function PaymentForm({ refs, request, close, saved }: { refs: Json; request: (path: string, options?: RequestInit) => Promise<Json>; close: () => void; saved: (payment: Json) => void }) {
  const [kind, setKind] = useState('RECEIPT'), [documents, setDocuments] = useState<Json[]>([]), [documentId, setDocumentId] = useState('');
  const [amount, setAmount] = useState(''), [bankAccountId, setBankAccountId] = useState(refs.bankAccounts[0]?.id || ''), [error, setError] = useState(''), [busy, setBusy] = useState(false);
  const remaining = useCallback((row: Json) => kind === 'RECEIPT' ? BigInt(row.remainingMinor) : BigInt(row.totalMinor) - BigInt(row.paidMinor), [kind]);
  useEffect(() => { request(`/documents?type=${kind === 'RECEIPT' ? 'SALES_INVOICE' : 'PURCHASE_BILL'}&status=POSTED`).then((rows) => { const open = rows.filter((row: Json) => remaining(row) > 0n); setDocuments(open); setDocumentId(open[0]?.id || ''); setAmount(open[0] ? (Number(remaining(open[0])) / 100).toFixed(2) : ''); }); }, [kind, request, remaining]);
  const selected = documents.find((row) => row.id === documentId);
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { saved(await request('/payments', { method: 'POST', body: JSON.stringify({ kind, branchId: refs.branches.find((branch: Json) => branch.code === 'CAI')?.id || refs.branches[0].id, bankAccountId, postingDate: today(), amount, method: refs.bankAccounts.find((account: Json) => account.id === bankAccountId)?.type === 'CASH' ? 'CASH' : 'BANK', customerId: selected?.customerId, supplierId: selected?.supplierId, allocations: [{ documentId, amount }] }) })); } catch (reason: any) { setError(reason.message); } finally { setBusy(false); } };
  return <Modal title="Allocate receipt or payment" close={close}><form className="form-grid" onSubmit={submit}><label className="field">{t('Direction', displayLanguage)}<select value={kind} onChange={(event) => setKind(event.target.value)}><option value="RECEIPT">{t('Customer receipt', displayLanguage)}</option><option value="PAYMENT">{t('Supplier payment', displayLanguage)}</option></select></label><label className="field">{t('Cash / bank account', displayLanguage)}<select value={bankAccountId} onChange={(event) => setBankAccountId(event.target.value)}>{refs.bankAccounts.map((account: Json) => <option key={account.id} value={account.id}>{account.code} · {referenceName(account.name)}</option>)}</select></label><label className="field full">{t('Open document', displayLanguage)}<select value={documentId} onChange={(event) => { const doc = documents.find((row) => row.id === event.target.value); setDocumentId(event.target.value); if (doc) setAmount((Number(remaining(doc))/100).toFixed(2)); }}>{documents.map((doc) => <option key={doc.id} value={doc.id}>{t(`${doc.number} · ${referenceName(doc.customer?.name || doc.supplier?.name)} · outstanding ${money(remaining(doc))}`, displayLanguage)}</option>)}</select></label><label className="field">{t('Allocation amount', displayLanguage)}<input value={amount} onChange={(event) => setAmount(event.target.value)} required/></label><label className="field">{t('Posting date', displayLanguage)}<input type="date" value={today()} readOnly/></label><p className="form-message">{error || (!documents.length ? t('There are no open posted documents for this direction.', displayLanguage) : '')}</p><div className="modal-actions full"><button type="button" className="button" onClick={close}>{t('Cancel', displayLanguage)}</button><button className="button primary" disabled={busy || !documentId}>{t(busy ? 'Posting allocation…' : 'Post and allocate', displayLanguage)}</button></div></form></Modal>;
}

function Pos({ refs, request, notify }: { refs: Json; request: (path: string, options?: RequestInit) => Promise<Json>; notify: (message: string, error?: boolean) => void }) {
  const [data, setData] = useState<Json>(null), [cart, setCart] = useState<Record<string, number>>({}), [tenders, setTenders] = useState({ CASH: '0.00', CARD: '0.00', BANK: '0.00' }), [search, setSearch] = useState(''), [customerId, setCustomerId] = useState(''), [discountPercent, setDiscountPercent] = useState('0'), [busy, setBusy] = useState(false);
  const load = useCallback(() => request('/pos').then(setData), [request]); useEffect(() => { load(); }, [load]);
  const shift = data?.shifts.find((row: Json) => row.status === 'OPEN');
  const cartLines = refs.items.filter((item: Json) => cart[item.id]).map((item: Json) => ({ item, quantity: cart[item.id] }));
  const totals = cartLines.reduce((sum: number, line: Json) => { const net = line.quantity * Number(line.item.salePriceMinor) / 100 * (1 - Number(discountPercent || 0) / 100); return sum + net * (1 + line.item.taxRateBps / 10000); }, 0);
  const add = (itemId: string, delta = 1) => setCart((current) => { const next = Math.max(0, (current[itemId] || 0) + delta); return { ...current, [itemId]: next }; });
  const openShift = async () => { setBusy(true); try { const cairo = refs.branches.find((branch: Json) => branch.code === 'CAI') || refs.branches[0]; const main = refs.warehouses.find((warehouse: Json) => warehouse.code === 'CAI-MAIN') || refs.warehouses.find((warehouse: Json) => warehouse.branchId === cairo.id) || refs.warehouses[0]; const result = await request('/pos/shifts', { method: 'POST', body: JSON.stringify({ branchId: cairo.id, warehouseId: main.id, registerCode: 'CAI-REG-01', openingCash: '1000.00' }) }); notify(`Shift ${result.registerCode} opened with counted cash`); await load(); } catch (error: any) { notify(error.message, true); } finally { setBusy(false); } };
  const checkout = async (hold = false) => { if (!shift) return notify('Open a shift first', true); setBusy(true); try { const tenderRows = Object.entries(tenders).filter(([, amount]) => Number(amount) > 0).map(([method, amount]) => ({ method, amount })); const sale = await request('/pos/sales', { method: 'POST', body: JSON.stringify({ shiftId: shift.id, customerId: customerId || undefined, hold, lines: cartLines.map((line: Json) => ({ itemId: line.item.id, quantity: line.quantity.toFixed(3), discount: (line.quantity * Number(line.item.salePriceMinor) / 100 * Number(discountPercent || 0) / 100).toFixed(2) })), tenders: tenderRows }) }); notify(`${sale.number} ${hold ? 'held for resume' : 'completed with stock and journal effects'}`); setCart({}); setTenders({ CASH: '0.00', CARD: '0.00', BANK: '0.00' }); await load(); } catch (error: any) { notify(error.message, true); } finally { setBusy(false); } };
  const closeShift = async () => { const actual = window.prompt(t('Count actual closing cash', displayLanguage), shift ? (Number(shift.expectedCashMinor)/100).toFixed(2) : '0.00'); if (actual === null || !shift) return; setBusy(true); try { const result = await request(`/pos/shifts/${shift.id}/close`, { method: 'POST', body: JSON.stringify({ actualCash: actual }) }); notify(`Shift closed · difference ${money(result.differenceMinor)}`); await load(); } catch (error: any) { notify(error.message, true); } finally { setBusy(false); } };
  const exactCash = () => setTenders({ CASH: totals.toFixed(2), CARD: '0.00', BANK: '0.00' });
  const splitTender = () => { const cash = Math.floor(totals * 50) / 100; setTenders({ CASH: cash.toFixed(2), CARD: (totals - cash).toFixed(2), BANK: '0.00' }); };
  const printReceipt = async (saleId: string) => { try { const response = await fetch(`${API}/pos/sales/${saleId}/pdf`, { headers: { Authorization: `Bearer ${localStorage.getItem('odin_token')}`, 'Accept-Language': displayLanguage, 'X-Odin-Language': displayLanguage } }); if (!response.ok) throw new Error(t('Receipt generation failed', displayLanguage)); window.open(URL.createObjectURL(await response.blob()), '_blank'); } catch (error: any) { notify(error.message, true); } };
  if (!data) return <Loading/>;
  return <div className="page"><PageHead title="Point of sale" subtitle="Shift control, held carts, split tenders, perpetual stock and same-transaction journals">{shift ? <><span className="status OPEN">{t(`${shift.registerCode} open · expected ${money(shift.expectedCashMinor)}`, displayLanguage)}</span><button className="button danger" disabled={busy} onClick={closeShift}>{t('Close shift', displayLanguage)}</button></> : <button className="button primary" disabled={busy} onClick={openShift}>{t('Open register shift', displayLanguage)}</button>}</PageHead>
    <div className="pos-layout"><section className="panel"><div className="panel-head"><h2>{t('PRODUCT CATALOG', displayLanguage)}</h2><span>{t('Search name, SKU, or scan barcode', displayLanguage)}</span></div><div className="toolbar"><input data-testid="pos-search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder={t('Search or scan barcode…', displayLanguage)}/></div><div className="pos-products">{refs.items.filter((item: Json) => `${item.name} ${item.nameAr} ${item.sku} ${item.barcode}`.toLowerCase().includes(search.toLowerCase())).map((item: Json) => <button key={item.id} className="pos-product" onClick={() => add(item.id)}><strong>{itemName(item)}</strong><span>{money(item.salePriceMinor)}</span><small>{item.sku} · {t('VAT', displayLanguage)} {item.taxRateBps/100}%</small></button>)}</div></section>
    <section className="panel cart"><div className="panel-head"><h2>{t('ACTIVE CART', displayLanguage)}</h2><span>{t(`${cartLines.length} items`, displayLanguage)}</span></div><div className="cart-lines">{cartLines.length ? cartLines.map((line: Json) => <div className="cart-line" key={line.item.id}><div><strong>{itemName(line.item)}</strong><span>{t(`${money(line.item.salePriceMinor)} each`, displayLanguage)}</span></div><div className="qty-control"><button aria-label={t('Decrease quantity', displayLanguage)} title={t('Decrease quantity', displayLanguage)} onClick={() => add(line.item.id, -1)}><AppIcon name="minus" size={13}/></button><b>{line.quantity}</b><button aria-label={t('Increase quantity', displayLanguage)} title={t('Increase quantity', displayLanguage)} onClick={() => add(line.item.id)}><AppIcon name="add" size={13}/></button></div><strong>{money(BigInt(Math.round(line.quantity * Number(line.item.salePriceMinor) * (1 - Number(discountPercent || 0)/100) * (1 + line.item.taxRateBps/10000))))}</strong><button className="cart-remove" aria-label={t('Remove line', displayLanguage)} title={t('Remove line', displayLanguage)} onClick={() => setCart((current) => ({ ...current, [line.item.id]: 0 }))}><AppIcon name="remove" size={14}/></button></div>) : <Empty icon="store" heading="Cart is empty" text="Select products from the catalog."/>}</div><div className="cart-summary"><label>{t('Customer', displayLanguage)}<select value={customerId} onChange={(event) => setCustomerId(event.target.value)}><option value="">{t('Walk-in customer', displayLanguage)}</option>{refs.customers.map((customer: Json) => <option key={customer.id} value={customer.id}>{customer.code} · {referenceName(customer.name)}</option>)}</select></label><label>{t('Discount % (cashier max 20)', displayLanguage)}<input type="number" min="0" max="20" value={discountPercent} onChange={(event) => setDiscountPercent(event.target.value)}/></label><div className="grand"><strong>{t('Total including VAT', displayLanguage)}</strong><strong>{money(BigInt(Math.round(totals*100)))}</strong></div><button className="button small" onClick={exactCash}>{t('Exact cash', displayLanguage)}</button> <button data-testid="split-tender" className="button small" onClick={splitTender}>{t('Split 50 / 50', displayLanguage)}</button><div className="tender-grid">{Object.entries(tenders).map(([method, amount]) => <label key={method}>{t(method, displayLanguage)}<input value={amount} onChange={(event) => setTenders({ ...tenders, [method]: event.target.value })}/></label>)}</div><div style={{ display: 'flex', gap: 7, marginTop: 12 }}><button className="button secondary" disabled={busy || !cartLines.length || !shift} onClick={() => checkout(true)}>{t('Hold', displayLanguage)}</button><button data-testid="pos-checkout" className="button primary" style={{ flex: 1 }} disabled={busy || !cartLines.length || !shift} onClick={() => checkout(false)}>{t('Complete split tender', displayLanguage)}</button></div></div></section></div>
    <div style={{ marginTop: 14 }}><Panel title="Shift and sale history" meta="Returns are linked reversals"><table><thead><tr><th>{t('Sale', displayLanguage)}</th><th>{t('Status', displayLanguage)}</th><th>{t('Shift', displayLanguage)}</th><th className="number">{t('Total', displayLanguage)}</th><th>{t('Tenders', displayLanguage)}</th><th>{t('Journal', displayLanguage)}</th><th>{t('Action', displayLanguage)}</th></tr></thead><tbody>{data.sales.map((sale: Json) => <tr key={sale.id}><td><strong>{sale.number}</strong></td><td><Status value={sale.status}/></td><td>{sale.shift.registerCode}</td><td className="number">{money(sale.totalMinor)}</td><td>{sale.tenders.map((tender: Json) => `${t(tender.method, displayLanguage)} ${money(tender.amountMinor)}`).join(' + ') || t('Held', displayLanguage)}</td><td>{sale.journalEntry?.number || '—'}</td><td>{sale.status !== 'HELD' && <button className="row-button" onClick={() => printReceipt(sale.id)}>{t('Receipt', displayLanguage)}</button>} {sale.status === 'HELD' && <button className="row-button" onClick={async () => { try { await request(`/pos/sales/${sale.id}/resume`, { method: 'POST', body: JSON.stringify({ tenders: [{ method: 'CASH', amount: (Number(sale.totalMinor)/100).toFixed(2) }] }) }); notify(`${sale.number} resumed and completed`); load(); } catch (error: any) { notify(error.message, true); } }}>{t('Resume', displayLanguage)}</button>}{sale.status === 'COMPLETED' && <button className="row-button" onClick={async () => { try { await request(`/pos/sales/${sale.id}/return`, { method: 'POST', body: JSON.stringify({ reason: 'UI customer return' }) }); notify(`${sale.number} returned with stock and journal reversal`); load(); } catch (error: any) { notify(error.message, true); } }}>{t('Return', displayLanguage)}</button>}</td></tr>)}</tbody></table></Panel></div><div style={{ marginTop: 14 }}><Panel title="POS shift closing report" meta="Expected versus actual cash and over / short journal"><table><thead><tr><th>{t('Register', displayLanguage)}</th><th>{t('Status', displayLanguage)}</th><th>{t('Opened', displayLanguage)}</th><th>{t('Closed', displayLanguage)}</th><th className="number">{t('Opening', displayLanguage)}</th><th className="number">{t('Expected', displayLanguage)}</th><th className="number">{t('Actual', displayLanguage)}</th><th className="number">{t('Difference', displayLanguage)}</th></tr></thead><tbody>{data.shifts.map((row: Json) => <tr key={row.id}><td>{row.registerCode}</td><td><Status value={row.status}/></td><td>{dateTime(row.openedAt)}</td><td>{dateTime(row.closedAt)}</td><td className="number">{money(row.openingCashMinor)}</td><td className="number">{money(row.expectedCashMinor)}</td><td className="number">{row.actualCashMinor === null ? '—' : money(row.actualCashMinor)}</td><td className="number">{row.differenceMinor === null ? '—' : money(row.differenceMinor)}</td></tr>)}</tbody></table></Panel></div></div>;
}

function Banking({ pageTitle, screenId, refs, request, notify, refreshRefs, canWrite, canReconcile }: { pageTitle: string; screenId: string; refs: Json; request: (path: string, options?: RequestInit) => Promise<Json>; notify: (message: string, error?: boolean) => void; refreshRefs: () => Promise<void>; canWrite: boolean; canReconcile: boolean }) {
  const [data, setData] = useState<Json>(null), [modal, setModal] = useState<'transaction' | 'statement' | 'bank' | ''>('');
  const load = useCallback(() => request('/banking').then(setData), [request]); useEffect(() => { load(); }, [load]);
  if (!data) return <Loading/>;
  const showTransactions = screenId === 'bank-transactions' || screenId === 'bank-reconciliation';
  const showStatements = screenId === 'bank-statements' || screenId === 'bank-reconciliation';
  return <div className="page"><PageHead title={pageTitle} subtitle="Posted receipts, payments, transfers and bank-statement matching">{showTransactions && canWrite && <button className="button primary" onClick={() => setModal('transaction')}><AppIcon name="add"/> {t('Bank transaction', displayLanguage)}</button>}{showStatements && canReconcile && <button className="button" onClick={() => setModal('statement')}>{t('Import statement line', displayLanguage)}</button>}</PageHead>
    <div className="metric-grid">{data.accounts.map((account: Json) => <Metric key={account.id} label={account.code} value={referenceName(account.name)} icon={account.type === 'CASH' ? 'money' : 'banking'}/>)}</div>
    <div className={showTransactions && showStatements ? 'split-view' : ''}>{showTransactions && <Panel title="Posted bank transactions" meta={`${data.transactions.length} records`}>{data.transactions.length ? <div className="table-wrap"><table><thead><tr><th>{t('Reference', displayLanguage)}</th><th>{t('Account', displayLanguage)}</th><th>{t('Kind', displayLanguage)}</th><th className="number">{t('Amount', displayLanguage)}</th><th>{t('Journal', displayLanguage)}</th><th>{t('Reconciliation', displayLanguage)}</th></tr></thead><tbody>{data.transactions.map((transaction: Json) => <tr key={transaction.id}><td><strong>{transaction.number}</strong><br/><span className="muted">{t(transaction.reference || transaction.description, displayLanguage)}</span></td><td>{referenceName(transaction.bankAccount.name)}</td><td>{title(transaction.kind)}</td><td className="number">{money(transaction.amountMinor)}</td><td>{transaction.journalEntry.number}</td><td>{transaction.reconciled ? <span className="reconciled"><AppIcon name="success" size={13}/> {t('Matched', displayLanguage)}</span> : <span className="muted">{t('Unmatched', displayLanguage)}</span>}</td></tr>)}</tbody></table></div> : <Empty icon="banking" heading="No banking transactions" text="Post a bank receipt, payment, or transfer."/>}</Panel>}
    {showStatements && <Panel title="Statement reconciliation" meta="Exact amount matching">{data.statements.length ? data.statements.map((statement: Json) => { const bookClosing = BigInt(statement.openingMinor) + statement.lines.reduce((sum: bigint, line: Json) => sum + BigInt(line.amountMinor), 0n); const statementDifference = BigInt(statement.closingMinor) - bookClosing; const unmatched = statement.lines.filter((line: Json) => !line.matched).reduce((sum: bigint, line: Json) => sum + (BigInt(line.amountMinor) < 0n ? -BigInt(line.amountMinor) : BigInt(line.amountMinor)), 0n); return <div key={statement.id} className="effect-card" style={{ marginBottom: 9 }}><h3>{referenceName(statement.bankAccount.name)} · {date(statement.statementDate)}</h3><p className={statementDifference === 0n && unmatched === 0n ? 'difference-zero' : 'difference-alert'}>{t(`Statement difference ${money(statementDifference)} · unmatched ${money(unmatched)}`, displayLanguage)}</p>{statement.lines.map((line: Json) => <div className="timeline-row" key={line.id}><i><AppIcon name={line.matched ? 'success' : 'help'} size={13}/></i><div><strong>{t(line.description, displayLanguage)} · {money(line.amountMinor)}</strong><span>{line.reference || t('No bank reference', displayLanguage)}</span></div>{line.matched ? <span className="reconciled">{t('Matched', displayLanguage)}</span> : canReconcile ? <select aria-label={t('Match transaction', displayLanguage)} defaultValue="" onChange={async (event) => { if (!event.target.value) return; try { await request(`/banking/statement-lines/${line.id}/match`, { method: 'POST', body: JSON.stringify({ transactionId: event.target.value }) }); notify('Statement line reconciled'); load(); } catch (error: any) { notify(error.message, true); } }}><option value="">{t('Match…', displayLanguage)}</option>{data.transactions.filter((transaction: Json) => !transaction.reconciled && transaction.bankAccountId === statement.bankAccountId && BigInt(transaction.amountMinor) === (BigInt(line.amountMinor) < 0n ? -BigInt(line.amountMinor) : BigInt(line.amountMinor))).map((transaction: Json) => <option key={transaction.id} value={transaction.id}>{transaction.number}</option>)}</select> : <span className="muted">{t('Read only', displayLanguage)}</span>}</div>)}</div>; }) : <Empty icon="checklist" heading="No imported statements" text="Import a line, then match it to a posted transaction."/>}</Panel>}</div>
    {modal === 'transaction' && <BankTransactionForm refs={refs} request={request} close={() => setModal('')} saved={(transaction) => { setModal(''); load(); notify(`${transaction.number} posted with journal ${transaction.journalEntry.number}`); }}/>} {modal === 'statement' && <StatementForm refs={refs} request={request} close={() => setModal('')} saved={() => { setModal(''); load(); notify('Bank statement line imported and awaiting match'); }}/>} {modal === 'bank' && <MasterForm kind="bank" refs={refs} request={request} close={() => setModal('')} saved={async (account) => { setModal(''); await refreshRefs(); await load(); notify(`${account.code} · ${account.name} created`); }}/>}</div>;
}

function BankTransactionForm({ refs, request, close, saved }: { refs: Json; request: (path: string, options?: RequestInit) => Promise<Json>; close: () => void; saved: (value: Json) => void }) {
  const counterparties = refs.accounts.filter((account: Json) => account.postingAllowed && !account.controlType);
  const [form, setForm] = useState({ kind: 'RECEIPT', bankAccountId: refs.bankAccounts[1]?.id || refs.bankAccounts[0]?.id, counterpartyAccountId: counterparties[0]?.id || '', amount: '500.00', description: t('Bank movement', displayLanguage), reference: 'BANK-REF-001' }), [busy, setBusy] = useState(false), [error, setError] = useState('');
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { saved(await request('/banking/transactions', { method: 'POST', body: JSON.stringify({ ...form, branchId: refs.branches[0].id, postingDate: today() }) })); } catch (reason: any) { setError(reason.message); } finally { setBusy(false); } };
  return <Modal title="Post bank transaction" close={close}><form className="form-grid" onSubmit={submit}><label className="field">{t('Kind', displayLanguage)}<select value={form.kind} onChange={(event) => setForm({ ...form, kind: event.target.value })}><option value="RECEIPT">{t('Receipt', displayLanguage)}</option><option value="PAYMENT">{t('Payment', displayLanguage)}</option><option value="TRANSFER_IN">{t('Transfer in', displayLanguage)}</option><option value="TRANSFER_OUT">{t('Transfer out / cash-bank transfer', displayLanguage)}</option></select></label><label className="field">{t('Cash / bank account', displayLanguage)}<select value={form.bankAccountId} onChange={(event) => setForm({ ...form, bankAccountId: event.target.value })}>{refs.bankAccounts.map((account: Json) => <option key={account.id} value={account.id}>{account.code} · {referenceName(account.name)}</option>)}</select></label><label className="field">{t(form.kind.startsWith('TRANSFER') ? 'Other cash / bank GL' : 'Counterparty GL', displayLanguage)}<select value={form.counterpartyAccountId} onChange={(event) => setForm({ ...form, counterpartyAccountId: event.target.value })}>{counterparties.map((account: Json) => <option key={account.id} value={account.id}>{account.code} · {referenceName(account.name)}</option>)}</select></label><label className="field">{t('Amount', displayLanguage)}<input value={form.amount} onChange={(event) => setForm({ ...form, amount: event.target.value })}/></label><label className="field">{t('Reference', displayLanguage)}<input value={form.reference} onChange={(event) => setForm({ ...form, reference: event.target.value })}/></label><label className="field">{t('Description', displayLanguage)}<input value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })}/></label><p className="form-message">{error}</p><div className="modal-actions full"><button type="button" className="button" onClick={close}>{t('Cancel', displayLanguage)}</button><button className="button primary" disabled={busy}>{t(busy ? 'Posting journal…' : 'Post transaction', displayLanguage)}</button></div></form></Modal>;
}

function StatementForm({ refs, request, close, saved }: { refs: Json; request: (path: string, options?: RequestInit) => Promise<Json>; close: () => void; saved: () => void }) {
  const [form, setForm] = useState({ bankAccountId: refs.bankAccounts[1]?.id || refs.bankAccounts[0]?.id, amount: '500.00', description: t('Imported bank line', displayLanguage), reference: 'BANK-REF-001', opening: '0.00', closing: '500.00' }), [busy, setBusy] = useState(false), [error, setError] = useState('');
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { await request('/banking/statements', { method: 'POST', body: JSON.stringify({ bankAccountId: form.bankAccountId, statementDate: today(), opening: form.opening, closing: form.closing, lines: [{ date: today(), amount: form.amount, description: form.description, reference: form.reference }] }) }); saved(); } catch (reason: any) { setError(reason.message); } finally { setBusy(false); } };
  return <Modal title="Import bank statement" close={close}><form className="form-grid" onSubmit={submit}><label className="field full">{t('Bank account', displayLanguage)}<select value={form.bankAccountId} onChange={(event) => setForm({ ...form, bankAccountId: event.target.value })}>{refs.bankAccounts.filter((account: Json) => account.type !== 'CARD_CLEARING').map((account: Json) => <option key={account.id} value={account.id}>{account.code} · {referenceName(account.name)}</option>)}</select></label><label className="field">{t('Opening balance', displayLanguage)}<input value={form.opening} onChange={(event) => setForm({ ...form, opening: event.target.value })}/></label><label className="field">{t('Closing balance', displayLanguage)}<input value={form.closing} onChange={(event) => setForm({ ...form, closing: event.target.value })}/></label><label className="field">{t('Line amount', displayLanguage)}<input value={form.amount} onChange={(event) => setForm({ ...form, amount: event.target.value })}/></label><label className="field">{t('Bank reference', displayLanguage)}<input value={form.reference} onChange={(event) => setForm({ ...form, reference: event.target.value })}/></label><label className="field full">{t('Description', displayLanguage)}<input value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })}/></label><p className="form-message">{error}</p><div className="modal-actions full"><button type="button" className="button" onClick={close}>{t('Cancel', displayLanguage)}</button><button className="button primary" disabled={busy}>{t(busy ? 'Importing…' : 'Import statement', displayLanguage)}</button></div></form></Modal>;
}

const reportCatalog = [
  ['trial-balance', 'Trial balance', 'Debits, credits and account balances'], ['general-ledger', 'General ledger', 'Journal lines with source drill-down'], ['account-ledger', 'Account ledger', 'Account-level debit, credit and balance'], ['income-statement', 'Income statement', 'Revenue, cost and current profit'], ['balance-sheet', 'Balance sheet', 'Assets, liabilities and equity'],
  ['customer-balances', 'Customer balances', 'Posted receivables by customer'], ['customer-statement', 'Customer statement', 'Invoices, receipts and running exposure'], ['supplier-statement', 'Supplier statement', 'Bills, payments and running exposure'], ['ar-aging', 'AR aging', 'Customer balances by due bucket'], ['ap-aging', 'AP aging', 'Supplier balances by due bucket'], ['inventory-valuation', 'Inventory valuation', 'On-hand quantity and moving value'], ['stock-movements', 'Stock movements', 'Custody history with source documents'],
  ['tax-report', 'VAT report', 'Output less recoverable input tax'], ['sales-profitability', 'Sales profitability', 'Revenue, source cost and margin'], ['purchase-analysis', 'Purchase analysis', 'Bills and returns by supplier'], ['cash-flow', 'Cash position', 'Cash, bank and card balances'], ['pos-shifts', 'POS shift report', 'Expected, actual, difference and closure'], ['reconciliation', 'Control reconciliation', 'AR, AP and inventory proof'],
];
const reportCategories: Record<string, string[]> = {
  sales: ['customer-balances', 'customer-statement', 'ar-aging', 'sales-profitability'],
  purchasing: ['supplier-statement', 'ap-aging', 'purchase-analysis'],
  inventory: ['inventory-valuation', 'stock-movements'],
  accounting: ['trial-balance', 'general-ledger', 'account-ledger', 'income-statement', 'balance-sheet', 'tax-report', 'reconciliation'],
  banking: ['cash-flow', 'reconciliation'],
  pos: ['pos-shifts'],
};
function Reports({ pageTitle, request, notify, canProfit, category, initialReport }: { pageTitle: string; request: (path: string, options?: RequestInit) => Promise<Json>; notify: (message: string, error?: boolean) => void; canProfit: boolean; category?: string; initialReport?: string }) {
  const permittedCatalog = reportCatalog.filter(([key]) => (canProfit || !['income-statement', 'balance-sheet', 'sales-profitability'].includes(key)) && (!category || reportCategories[category]?.includes(key)));
  const defaultReport = initialReport && permittedCatalog.some(([key]) => key === initialReport) ? initialReport : permittedCatalog[0]?.[0] || 'reconciliation';
  const [selected, setSelected] = useState(defaultReport), [report, setReport] = useState<Json>(null), [drill, setDrill] = useState<Json>(null), [busy, setBusy] = useState(false);
  const load = useCallback(async (name: string) => { setBusy(true); try { setReport(await request(`/reports/${name}`)); } catch (error: any) { notify(error.message, true); } finally { setBusy(false); } }, [request, notify]);
  useEffect(() => { load(selected); }, [selected, load]);
  useEffect(() => { setSelected(defaultReport); }, [defaultReport]);
  const download = async (format: 'csv' | 'pdf') => { try { const response = await fetch(`${API}/reports/${selected}/${format}`, { headers: { Authorization: `Bearer ${localStorage.getItem('odin_token')}`, 'Accept-Language': displayLanguage, 'X-Odin-Language': displayLanguage } }); if (!response.ok) throw new Error(t('Export failed', displayLanguage)); const url = URL.createObjectURL(await response.blob()); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `${selected}.${format}`; anchor.click(); URL.revokeObjectURL(url); notify(`${t(report.name, displayLanguage)} ${format.toUpperCase()} exported`); } catch (error: any) { notify(error.message, true); } };
  const columns = report?.rows?.length ? Object.keys(report.rows[0]).filter((key) => typeof report.rows[0][key] !== 'object') : [];
  const inspect = async (reference: string) => { try { setDrill(await request(`/evidence/${encodeURIComponent(reference)}`)); } catch (error: any) { notify(error.message, true); } };
  return <div className="page report-page"><PageHead title={pageTitle} subtitle="Business reports calculated from posted journals and operational ledgers"><button className="button" onClick={() => window.print()}><AppIcon name="print" size={15}/>{t('Browser print', displayLanguage)}</button><button className="button" onClick={() => download('csv')}><AppIcon name="csv" size={15}/>{t('Export CSV', displayLanguage)}</button><button className="button primary" onClick={() => download('pdf')}><AppIcon name="pdf" size={15}/>{t('Print PDF', displayLanguage)}</button></PageHead>
    <div className="report-catalog">{permittedCatalog.map(([key, label, description]) => <button key={key} className={`report-tile ${selected === key ? 'active' : ''}`} onClick={() => setSelected(key)}><i><AppIcon name="reports"/></i><strong>{t(label, displayLanguage)}</strong><span>{t(description, displayLanguage)}</span></button>)}</div>
    <div className="report-output data-panel"><div className="panel-head"><h2>{t(report?.name || 'Report', displayLanguage)}</h2><span>{t('Select a reference to view the supporting transaction', displayLanguage)}</span></div>{busy ? <Loading/> : report?.rows?.length ? <div className="table-wrap"><table><thead><tr>{columns.map((column) => <th key={column} className={column.toLowerCase().includes('minor') ? 'number' : ''}>{t(baseTitle(column.replace('Minor','')), displayLanguage)}</th>)}</tr></thead><tbody>{report.rows.map((row: Json, index: number) => <tr key={index}>{columns.map((column) => { const value = row[column]; const isMoney = column.toLowerCase().includes('minor'); const isQty = column.toLowerCase().includes('quantity'); const difference = column === 'differenceMinor'; const isReference = ['journal', 'number', 'reference', 'source', 'sourceNumber'].includes(column) && typeof value === 'string'; return <td key={column} className={`${isMoney ? 'number' : ''} ${difference ? (BigInt(value || 0) === 0n ? 'difference-zero' : 'difference-alert') : ''}`}>{isReference ? <button className="link-button" onClick={() => inspect(value)}>{value}</button> : isMoney ? money(value) : isQty ? qty(value) : t(String(value ?? '—'), displayLanguage)}</td>; })}</tr>)}</tbody></table>{report.totals && <div className="summary-box">{Object.entries(report.totals).map(([key, value]) => <div key={key}><span>{t(baseTitle(key.replace('Minor','')), displayLanguage)}</span><strong>{key.includes('Minor') ? money(value as string) : t(String(value), displayLanguage)}</strong></div>)}</div>}</div> : <Empty heading="No rows for this report" text="Post transactions to populate it."/>}</div>{drill && <Modal title={`${t(drill.kind, displayLanguage)} ${drill.reference}`} close={() => setDrill(null)} wide><div className="detail-grid">{Object.entries(drill).filter(([key, value]) => key !== 'lines' && key !== 'stockMovements' && typeof value !== 'object').map(([key, value]) => <Detail key={key} label={t(baseTitle(key), displayLanguage)} value={key.toLowerCase().includes('minor') ? money(value as string) : t(String(value ?? '—'), displayLanguage)}/>)}</div><EffectTable title="Underlying lines" rows={(drill.lines || []).map((line: string) => ({ Evidence: t(line, displayLanguage) }))}/><EffectTable title="Inventory movements" rows={(drill.stockMovements || []).map((line: string) => ({ Movement: t(line, displayLanguage) }))}/></Modal>}</div>;
}

function Audit({ pageTitle, request, notify, canReset }: { pageTitle: string; request: (path: string, options?: RequestInit) => Promise<Json>; notify: (message: string, error?: boolean) => void; canReset: boolean }) {
  const [events, setEvents] = useState<Json[]>([]); useEffect(() => { request('/audit').then(setEvents); }, [request]);
  const reset = async () => { const confirmation = window.prompt(t('Type RESET ODIN to rebuild the demo tenant', displayLanguage)); if (confirmation !== 'RESET ODIN') return; const password = window.prompt(t('Re-enter the administrator password', displayLanguage)); if (!password) return; try { const result = await request('/system/reset', { method: 'POST', body: JSON.stringify({ confirmation, password }) }); window.alert(`${t(result.message, displayLanguage)}\n${t('Balanced journals', displayLanguage)}: ${t(result.integrity.postedJournalsBalanced ? 'PASS' : 'FAIL', displayLanguage)}\n${t('Inventory difference', displayLanguage)}: ${money(result.integrity.inventoryDifferenceMinor)}\n${t('Negative stock rows', displayLanguage)}: ${result.integrity.negativeStockRows}`); notify(result.message); localStorage.removeItem('odin_token'); window.setTimeout(() => window.location.reload(), 300); } catch (error: any) { notify(error.message, true); } };
  return <div className="page"><PageHead title={pageTitle} subtitle="Actor, entity, action, posting/approval reference and recorded payload"><span className="status OPEN">{t('Database mutation guard active', displayLanguage)}</span>{canReset && <button className="button danger" onClick={reset}>{t('Reset demo tenant', displayLanguage)}</button>}</PageHead><div className="integrity-banner"><AppIcon name="lock" size={23}/><div><strong>{t('Evidence is append-only at PostgreSQL trigger level', displayLanguage)}</strong><span>{t('Application-role UPDATE and DELETE attempts against audit events are rejected.', displayLanguage)}</span></div></div><div className="data-panel">{events.length ? <div className="table-wrap"><table><thead><tr><th>{t('Timestamp', displayLanguage)}</th><th>{t('Actor', displayLanguage)}</th><th>{t('Action', displayLanguage)}</th><th>{t('Entity', displayLanguage)}</th><th>{t('Reference', displayLanguage)}</th><th>{t('Recorded values', displayLanguage)}</th></tr></thead><tbody>{events.map((event) => <tr key={event.id}><td>{dateTime(event.createdAt)}</td><td><strong>{t(event.user.name, displayLanguage)}</strong><br/><span className="muted">{event.user.email}</span></td><td><Status value={event.action}/></td><td>{t(event.entityType, displayLanguage)} · {event.entityId}</td><td>{event.postingReference || event.approvalReference || '—'}</td><td>{auditValues(event.newValues)}</td></tr>)}</tbody></table></div> : <Loading/>}</div></div>;
}
